LESSONS.push(
{id:15,th:'ร่างกายและสุขภาพ',zh:'身体好吗',chapter:201,emoji:'🩺',
 story:'ลามะเล่นน้ำฝนเมื่อวานจนไม่สบาย! ต้องไปหาหมอและบอกอาการให้ถูก ปวดหัว ปวดท้อง อ่อนเพลีย พร้อมคำแนะนำให้พักผ่อน',
 words:[
 W('身体','shēn|tǐ','ร่างกาย / สุขภาพ','เซิน-ถี่','身 (ตัว) + 体 (ร่าง) = ร่างกาย · ใช้ถามสุขภาพว่า 身体好吗？','爷爷身体很好。','Yé|ye shēn|tǐ hěn hǎo.','คุณปู่สุขภาพดีมาก'),
 W('头','tóu','หัว','โถว','ตัวช่วยจำ: ส่วนล่าง 大 มองเหมือนคนมีหัวใหญ่ · ใช้ต่อท้ายหลายคำ เช่น 前头 (ข้างหน้า)','我的头很大。','Wǒ de tóu hěn dà.','หัวฉันใหญ่มาก'),
 W('手','shǒu','มือ','โสว่','ตัวช่วยจำ: ภาพฝ่ามือกับนิ้วที่กางออก · ตัวอักษรที่มีส่วน 扌ด้านซ้ายมักเกี่ยวกับมือ','我的手很冷。','Wǒ de shǒu hěn lěng.','มือฉันเย็นมาก'),
 W('脚','jiǎo','เท้า','เจี่ยว','เสียงเหมือน “เจี๊ยว” แต่กดต่ำ · 月 (เนื้อ/ร่างกาย) อยู่ซ้าย','我的脚很疼。','Wǒ de jiǎo hěn téng.','เท้าฉันเจ็บมาก'),
 W('眼睛','yǎn|jing','ตา','เหยี่ยน-จิง','ทั้งสองตัวมี 目 (ตา) อยู่ซ้าย','她的眼睛很大。','Tā de yǎn|jing hěn dà.','ตาเธอโตมาก'),
 W('肚子','dù|zi','ท้อง','ตู้-จึ','肚 + 子 ท้ายคำเสียงเบา · ใช้ทั้งท้องคนและท้องสัตว์','我的肚子很饿。','Wǒ de dù|zi hěn è.','ท้องฉันหิวมาก'),
 W('疼','téng','เจ็บ / ปวด','เถิง','เสียง “เถิง” — จำว่า เจ็บจนต้อง เถิง (ร้องครวญ)','我头疼。','Wǒ tóu téng.','ฉันปวดหัว'),
 W('头疼','tóu téng','ปวดหัว','โถว-เถิง','头 + 疼 = ปวดหัว · ใช้เป็นอาการยอดฮิต','我今天头疼。','Wǒ jīn|tiān tóu téng.','วันนี้ฉันปวดหัว'),
 W('生病','shēng bìng','ป่วย / ไม่สบาย','เซิง-ปิ่ง','生 (เกิด/เกิดขึ้น) + 病 (โรค) = เกิดโรค','弟弟生病了。','Dì|di shēng bìng le.','น้องชายป่วยแล้ว'),
 W('感冒','gǎn|mào','เป็นหวัด','ก่าน-เม่า','感 (รู้สึก/ติด) + 冒 (ผุด) = ติดหวัด · 冷 ที่เรียนแล้วช่วยโยงกับอากาศหนาว','我感冒了，不想吃饭。','Wǒ gǎn|mào le, bù xiǎng chī fàn.','ฉันเป็นหวัด ไม่อยากกินข้าว'),
 W('药','yào','ยา','เย่า','ตัวช่วยจำ: มีหญ้า (艹) อยู่ข้างบน เพราะยาสมัยก่อนทำจากสมุนไพร','我要吃药。','Wǒ yào chī yào.','ฉันต้องกินยา'),
 W('休息','xiū|xi','พักผ่อน','ซิว-สี','休 = คน (亻) พิงต้นไม้ (木) ตัวช่วยจำ: คนพิงไม้พัก · 息 อ่านเบา','你要多休息。','Nǐ yào duō xiū|xi.','คุณต้องพักผ่อนให้มาก ๆ'),
 W('累','lèi','เหนื่อย','เล่ย','เสียง “เล่ย” ฟังเหมือน “เหนื่อย” เลย','今天我很累。','Jīn|tiān wǒ hěn lèi.','วันนี้ฉันเหนื่อยมาก'),
 W('饿','è','หิว','เอ่อ','มี 饣 (อาหาร) ทางซ้าย · เสียง 4 ตกเร็วเหมือนท้องร้อง','我饿了，想吃米饭。','Wǒ è le, xiǎng chī mǐ|fàn.','ฉันหิวแล้ว อยากกินขนมปัง'),
 W('渴','kě','กระหายน้ำ','เค่อ','มี 氵 (น้ำ) ทางซ้าย บอกว่าอยากได้น้ำ','我很渴，想喝水。','Wǒ hěn kě, xiǎng hē shuǐ.','ฉันกระหายมาก อยากดื่มน้ำ'),
 W('要','yào','ต้อง / จะ / ต้องการ','เย่า','要 + กริยา = ต้อง/จะทำ · เสียงเดียวกับ 药 (ยา) แต่คนละความหมาย ดูบริบท','我要喝水。','Wǒ yào hē shuǐ.','ฉันจะดื่มน้ำ')],
 sents:[['你/头/疼/吗？','nǐ/tóu/téng/ma?','คุณปวดหัวไหม'],['我/头疼，/肚子/也/疼。','wǒ/tóu téng,/dù|zi/yě/téng.','ฉันปวดหัว ท้องก็ปวด'],['你/要/多/休息。','nǐ/yào/duō/xiū|xi.','คุณต้องพักผ่อนมาก ๆ'],['我/感冒/了，/要/吃药。','wǒ/gǎn|mào/le,/yào/chī yào.','ฉันเป็นหวัด ต้องกินยา'],['我/饿/了，/也/渴/了。','wǒ/è/le,/yě/kě/le.','ฉันหิวแล้วและก็กระหายด้วย'],['你/的/身体/好/吗？','nǐ/de/shēn|tǐ/hǎo/ma?','สุขภาพคุณดีไหม']],
 dlg:[['t','你怎么了？','nǐ zěn|me le?','คุณเป็นอะไรไป'],['f','我头疼，我感冒了。','wǒ tóu téng, wǒ gǎn|mào le.','ฉันปวดหัว ฉันเป็นหวัด'],['t','你要多休息，多喝水。','nǐ yào duō xiū|xi, duō hē shuǐ.','พักผ่อนมาก ๆ ดื่มน้ำเยอะ ๆ'],['f','好的，谢谢医生。','hǎo de, xiè|xie yī|shēng.','ได้ครับ ขอบคุณคุณหมอ']],
 rq:{p:0,wrong:[['六口人，爷爷奶奶、爸爸妈妈和我。','liù kǒu rén, yé|ye nǎi|nai, bà|ba mā|ma hé wǒ.','หกคน ปู่ย่า พ่อแม่และฉัน'],['晚上七点，欢迎你和朋友一起来。','Wǎn|shang qī diǎn, huān|yíng nǐ hé péng|you yì|qǐ lái.','หนึ่งทุ่ม ยินดีต้อนรับคุณกับเพื่อนมาด้วยกัน']]}},
{id:105,th:'สั่งชานมไข่มุก',zh:'点奶茶',chapter:46,emoji:'🧋',
 story:'ลามะเข้าร้านชานมไข่มุกในจีน เรียนสั่งขนาดแก้ว ระดับความหวาน น้ำแข็ง และสั่งกลับบ้านให้ถูกต้อง',
 words:[
 W('奶茶','nǎi|chá','ชานม','ไหน่-ฉ๋า','奶 (นม) + 茶 (ชา) = ชาผสมนม','我想喝一杯奶茶。','Wǒ xiǎng hē yì bēi nǎi|chá.','ฉันอยากดื่มชานมสักแก้ว'),
 W('珍珠','zhēn|zhū','ไข่มุก (ในชานม)','เจิน-จู','珍 (มีค่า) + 珠 (เม็ดกลม) = ไข่มุก','奶茶里的珍珠又软又甜。','Nǎi|chá lǐ de zhēn|zhū yòu ruǎn yòu tián.','ไข่มุกในชานมทั้งนุ่มทั้งหวาน'),
 W('吸管','xī|guǎn','หลอดดูด','ซี-กว่าน','吸 (ดูด) + 管 (ท่อ) = ท่อที่ใช้ดูด','请给我一根吸管。','Qǐng gěi wǒ yì gēn xī|guǎn.','ขอหลอดให้ฉันหนึ่งอัน'),
 W('果汁','guǒ|zhī','น้ำผลไม้','กั่ว-จือ','果 (ผลไม้) + 汁 (น้ำคั้น) = น้ำคั้นจากผลไม้','我要一杯西瓜果汁。','Wǒ yào yì bēi xī|guā guǒ|zhī.','ฉันขอน้ำแตงโมปั่นหนึ่งแก้ว'),
 W('可乐','kě|lè','โคล่า','เข่อ-เล่อ','可乐 = เสียงทับศัพท์ของ Cola (แปลว่าน่าสนุกด้วย)','他每天都喝可乐。','Tā měi|tiān dōu hē kě|lè.','เขาดื่มโคล่าทุกวัน'),
 W('啤酒','pí|jiǔ','เบียร์','ผี๋-จิ่ว','啤 (เสียงทับศัพท์ beer) + 酒 (เหล้า) = เหล้าเบียร์','爸爸吃晚饭的时候喝一瓶啤酒。','Bà|ba chī wǎn|fàn de shí|hou hē yì píng pí|jiǔ.','ตอนกินข้าวเย็นพ่อดื่มเบียร์หนึ่งขวด'),
 W('茶叶','chá|yè','ใบชา','ฉ๋า-เย่','茶 (ชา) + 叶 (ใบ) = ใบของต้นชา','这是朋友送我的茶叶。','Zhè shì péng|you sòng wǒ de chá|yè.','นี่คือใบชาที่เพื่อนให้ฉัน'),
 W('绿茶','lǜ|chá','ชาเขียว','หลวี่-ฉ๋า','绿 (เขียว) + 茶 (ชา) = ชาสีเขียว','我喜欢喝不加糖的绿茶。','Wǒ xǐ|huan hē bù jiā táng de lǜ|chá.','ฉันชอบดื่มชาเขียวไม่ใส่น้ำตาล'),
 W('红茶','hóng|chá','ชาดำ','หง๋ง-ฉ๋า','红 (แดง) + 茶 (ชา) = ชาน้ำสีแดง (ชาดำ)','英国人喜欢在下午喝红茶。','Yīng|guó rén xǐ|huan zài xià|wǔ hē hóng|chá.','คนอังกฤษชอบดื่มชาดำตอนบ่าย'),
 W('大杯','dà|bēi','แก้วใหญ่','ต้า-เปย','大 (ใหญ่) + 杯 (แก้ว) = แก้วขนาดใหญ่','我要大杯的，谢谢。','Wǒ yào dà|bēi de, xiè|xie.','ฉันขอแก้วใหญ่ ขอบคุณ'),
 W('中杯','zhōng|bēi','แก้วกลาง','จง-เปย','中 (กลาง) + 杯 (แก้ว) = แก้วขนาดกลาง','中杯够了，我不太渴。','Zhōng|bēi gòu le, wǒ bú tài kě.','แก้วกลางพอแล้ว ฉันไม่ค่อยกระหาย'),
 W('小杯','xiǎo|bēi','แก้วเล็ก','เสี่ยว-เปย','小 (เล็ก) + 杯 (แก้ว) = แก้วขนาดเล็ก','小杯只要八块钱。','Xiǎo|bēi zhǐ yào bā kuài qián.','แก้วเล็กแค่แปดหยวน'),
 W('少糖','shǎo|táng','หวานน้อย','เส่า-ถาง๋','少 (น้อย) + 糖 (น้ำตาล) = น้ำตาลน้อย','我不想吃太甜，请少糖。','Wǒ bù xiǎng chī tài tián, qǐng shǎo|táng.','ฉันไม่อยากให้หวานเกินไป ขอหวานน้อย'),
 W('加冰','jiā|bīng','ใส่น้ำแข็ง','เจีย-ปิง','加 (เพิ่ม) + 冰 (น้ำแข็ง) = เพิ่มน้ำแข็ง','夏天我喜欢加冰。','Xià|tiān wǒ xǐ|huan jiā|bīng.','หน้าร้อนฉันชอบใส่น้ำแข็ง'),
 W('去冰','qù|bīng','ไม่ใส่น้ำแข็ง','ชวี่-ปิง','去 (เอาออก) + 冰 (น้ำแข็ง) = เอาน้ำแข็งออก','今天很冷，请去冰。','Jīn|tiān hěn lěng, qǐng qù|bīng.','วันนี้หนาวมาก ขอไม่ใส่น้ำแข็ง'),
 W('外带','wài|dài','ซื้อกลับ / ห่อกลับ','หว่าย-ไต้','外 (ข้างนอก) + 带 (นำไป) = นำออกไปข้างนอก','在这里喝还是外带？','Zài zhè|lǐ hē hái|shi wài|dài?','ดื่มที่นี่หรือห่อกลับ')],
 sents:[['我/想/喝/一/杯/奶茶。','wǒ/xiǎng/hē/yì/bēi/nǎi|chá.','ฉันอยากดื่มชานมสักแก้ว'],['请/给/我/一/根/吸管。','qǐng/gěi/wǒ/yì/gēn/xī|guǎn.','ขอหลอดให้ฉันหนึ่งอัน'],['我/要/大杯/的。','wǒ/yào/dà|bēi/de.','ฉันขอแก้วใหญ่'],['请/少糖/去冰。','qǐng/shǎo|táng/qù|bīng.','ขอหวานน้อยและไม่ใส่น้ำแข็ง'],['夏天/我/喜欢/加冰。','xià|tiān/wǒ/xǐ|huan/jiā|bīng.','หน้าร้อนฉันชอบใส่น้ำแข็ง'],['在/这里/喝/还是/外带？','zài/zhè|lǐ/hē/hái|shi/wài|dài?','ดื่มที่นี่หรือห่อกลับ']],
 dlg:[['t','你好，请问要喝点儿什么？','Nǐ hǎo, qǐng|wèn yào hē diǎn|r shén|me?','สวัสดีค่ะ จะดื่มอะไรดีคะ'],['f','一杯珍珠奶茶，大杯，少糖去冰。','Yì bēi zhēn|zhū nǎi|chá, dà bēi, shǎo táng qù bīng.','ชานมไข่มุกหนึ่งแก้ว แก้วใหญ่ หวานน้อยไม่ใส่น้ำแข็ง'],['t','好的，在这里喝还是外带？','Hǎo de, zài zhè|lǐ hē hái|shi wài|dài?','ได้ค่ะ ดื่มที่นี่หรือห่อกลับคะ'],['f','外带，请给我一根吸管。','Wài|dài, qǐng gěi wǒ yì gēn xī|guǎn.','ห่อกลับ ขอหลอดหนึ่งอันด้วยครับ']],
 rq:{p:0,wrong:[['别担心，给他们发邮件。','bié dān|xīn, gěi tā|men fā yóu|jiàn.','อย่ากังวล ส่งอีเมลหาเขาสิ'],['别着急，我会打电话告诉你。','Bié zháo|jí, wǒ huì dǎ diàn|huà gào|su nǐ.','อย่าร้อนใจ ฉันจะโทรไปบอกคุณ']]}},
{id:117,th:'คำบอกลักษณะที่ใช้ทุกวัน',zh:'常用的词',chapter:58,emoji:'✨',
 story:'ลามะเรียนคำบอกลักษณะง่ายๆ ที่ใช้บ่อย เช่น นุ่ม หนา สว่าง ยาว สั้น ผิด เร็ว และสวย แล้วชวนเพื่อนไปดูหนัง',
 words:[
 W('坏','huài','เสีย / แย่ / ไม่ดี','ฮ่วย','ใช้ได้ทั้งของที่เสียและคนที่นิสัยไม่ดี · ตรงข้ามกับ 好','这个苹果坏了。','Zhè ge píng|guǒ huài le.','แอปเปิลลูกนี้เสียแล้ว'),
 W('奇怪','qí|guài','แปลก / ประหลาด','ฉี-กวาย','奇 (แปลก) + 怪 (ประหลาด)','这件事很奇怪。','Zhè jiàn shì hěn qí|guài.','เรื่องนี้แปลกมาก'),
 W('软','ruǎn','นุ่ม','รว่าน','车 (รถ) + 欠 (เสียงอ่านเก่า) = นุ่มสบาย','沙发很软。','Shā|fā hěn ruǎn.','โซฟานุ่มมาก'),
 W('清楚','qīng|chu','ชัดเจน / เข้าใจชัด','ชิง-ฉู่','清 (ใส) + 楚 (ชัด) · ตัว 楚 ท้ายออกเสียงเบา','你说得很清楚。','Nǐ shuō de hěn qīng|chu.','คุณพูดชัดเจนมาก'),
 W('错','cuò','ผิด','ชั่ว','钅 (โลหะ) + 昔 (เสียงอ่าน) = ผิดพลาด','这个字写错了。','Zhè|ge zì xiě cuò le.','ตัวอักษรนี้เขียนผิด'),
 W('快','kuài','เร็ว','ไคว่','忄 (ใจ) + 夬 (เสียงอ่าน) = ใจเบิกบานจนทำเร็ว','快点儿走吧。','Kuài diǎn|r zǒu ba.','รีบเดินหน่อยเถอะ'),
 W('早','zǎo','เช้า / เร็ว','จ่าว','日 (ดวงอาทิตย์) + 十 = ตอนอาทิตย์เพิ่งขึ้น','早，你吃早饭了吗？','Zǎo, nǐ chī zǎo|fàn le ma?','อรุณสวัสดิ์ กินข้าวเช้าหรือยัง'),
 W('晚','wǎn','ช้า / ค่ำ','หว่าน','日 (ดวงอาทิตย์) + 免 (เสียงอ่าน) = เวลาที่ตะวันลับ','对不起，我来晚了。','Duì|bu|qǐ, wǒ lái wǎn le.','ขอโทษ ฉันมาช้าไป'),
 W('有名','yǒu|míng','มีชื่อเสียง','โหย่ว-หมิง','有 (มี) + 名 (ชื่อ) = มีชื่อเสียง','这家店很有名。','Zhè jiā diàn hěn yǒu|míng.','ร้านนี้มีชื่อเสียงมาก'),
 W('相同','xiāng|tóng','ตรงกัน / เหมือนกันทุกประการ','เซียง-ถง','相 (กัน) + 同 (เหมือน) = เหมือนกัน','我们的爱好相同。','Wǒ|men de ài|hào xiāng|tóng.','ความชอบของเราเหมือนกัน'),
 W('厚','hòu','หนา','โฮ่ว','厂 (ผา) + 日 + 子 = หนาหนัก','这本书很厚。','Zhè běn shū hěn hòu.','หนังสือเล่มนี้หนามาก'),
 W('亮','liàng','สว่าง','เลี่ยง','亠 + 口 + 几 = ไฟสว่างบนอาคาร','房间里很亮。','Fáng|jiān lǐ hěn liàng.','ในห้องสว่างมาก'),
 W('长','cháng','ยาว','ฉาง๋','长 = รูปคนผมยาว','这条路很长。','Zhè tiáo lù hěn cháng.','ถนนเส้นนี้ยาวมาก'),
 W('短','duǎn','สั้น','ต่วน','矢 (ลูกธนู) + 豆 = สั้นเหมือนธนูสั้น','她的头发很短。','Tā de tóu|fa hěn duǎn.','ผมของเธอสั้นมาก'),
 W('好看','hǎo|kàn','สวย / ดูดี','ห่าว-คั่น','好 (ดี) + 看 (ดู) = ดูแล้วดี','这件衣服很好看。','Zhè jiàn yī|fu hěn hǎo|kàn.','เสื้อตัวนี้สวยมาก'),
 W('热情','rè|qíng','เป็นมิตร / อบอุ่น','เย่อ-ฉิง๋','热 (ร้อน) + 情 (น้ำใจ) = น้ำใจอบอุ่น','老师很热情。','Lǎo|shī hěn rè|qíng.','ครูใจดีและอบอุ่นมาก')],
 sents:[['沙发/很/软。','shā|fā/hěn/ruǎn.','โซฟานุ่มมาก'],['这/本/书/很/厚。','zhè/běn/shū/hěn/hòu.','หนังสือเล่มนี้หนามาก'],['这/个/字/写/错/了。','zhè/ge/zì/xiě/cuò/le.','ตัวอักษรนี้เขียนผิด'],['快/点儿/走/吧。','kuài/diǎn|r/zǒu/ba.','รีบเดินหน่อยเถอะ'],['这/件/衣服/很/好看。','zhè/jiàn/yī|fu/hěn/hǎo|kàn.','เสื้อตัวนี้สวยมาก'],['她/的/头发/很/短。','tā/de/tóu|fa/hěn/duǎn.','ผมของเธอสั้นมาก']],
 dlg:[['t','你今天忙不忙？','Nǐ jīn|tiān máng bu máng?','วันนี้เธอยุ่งไหม'],['f','不忙，不过我有点儿累。','Bù máng, bú guò wǒ yǒu diǎn|r lèi.','ไม่ยุ่ง แต่ฉันเหนื่อยนิดหน่อย'],['t','那我们去看电影吧，这个电影很好看。','Nà wǒ|men qù kàn diàn|yǐng ba, zhè|ge diàn|yǐng hěn hǎo|kàn.','งั้นเราไปดูหนังกัน หนังเรื่องนี้สนุกมาก'],['f','好啊，我们早点儿去。','Hǎo a, wǒ|men zǎo diǎn|r qù.','ดี เราไปเร็วหน่อยเถอะ']],
 rq:{p:0,wrong:[['我喜欢蓝色和白色。','wǒ xǐ|huan lán sè hé bái sè.','ฉันชอบสีฟ้ากับสีขาว'],['我喜欢地理，因为可以看很多地图。','Wǒ xǐ|huan dì|lǐ, yīn|wèi kě|yǐ kàn hěn|duō dì|tú.','ฉันชอบภูมิศาสตร์ เพราะได้ดูแผนที่เยอะ']]}},
{id:23,th:'เปรียบเทียบและบอกระดับ',zh:'比一比',chapter:204,emoji:'📏',
 story:'ลามะกับเพื่อนแข่งกันเล่นทุกอย่าง ใครสูงกว่า ใครวิ่งเร็วกว่า ใครขยันที่สุด ต้องเรียนวิธีเปรียบเทียบที่ใช้ได้ทุกวัน',
 words:[
 W('比','bǐ','เทียบกับ / กว่า','ปี่','A 比 B + คำคุณศัพท์ = A …กว่า B เช่น 他比我高 = เขาสูงกว่าฉัน','他比我高。','Tā bǐ wǒ gāo.','เขาสูงกว่าฉัน'),
 W('更','gèng','ยิ่ง / …ขึ้นอีก','เก้ง','ใช้เมื่อเทียบแล้วยิ่งขึ้นกว่าเดิม เช่น 更好 = ดียิ่งขึ้น','今天更冷。','Jīn|tiān gèng lěng.','วันนี้หนาวยิ่งกว่า'),
 W('最','zuì','ที่สุด','จุ้ย','เจอตัว 最 + คำคุณศัพท์ = ที่สุดในกลุ่ม เช่น 最大 ใหญ่ที่สุด','他最高。','Tā zuì gāo.','เขาสูงที่สุด'),
 W('一样','yí|yàng','เหมือนกัน','อี๋-ย่าง','一 (หนึ่ง) + 样 (แบบ) = แบบเดียวกัน · 一 เปลี่ยนเป็นเสียง 2 ก่อนเสียง 4','我和他一样大。','Wǒ hé tā yí|yàng dà.','ฉันกับเขาอายุเท่ากัน (ใหญ่เท่ากัน)'),
 W('非常','fēi|cháng','อย่างยิ่ง / มาก ๆ','เฟย-ฉ๋าง','非 (ไม่ใช่) + 常 (ธรรมดา) = ไม่ธรรมดาเลย → มากเป็นพิเศษ','今天非常热。','Jīn|tiān fēi|cháng rè.','วันนี้ร้อนมาก'),
 W('特别','tè|bié','พิเศษ / เป็นพิเศษ','เทอ่-เปี๋ย','特 (พิเศษ) + 别 (แยก) · ใช้เหมือน 很 แต่เน้นกว่า','这个菜特别好吃。','Zhè|ge cài tè|bié hǎo|chī.','อาหารจานนี้อร่อยเป็นพิเศษ'),
 W('高','gāo','สูง','เกา','เจอใน 高兴 · ใช้ทั้งความสูงของคนและของ','他很高。','Tā hěn gāo.','เขาสูงมาก'),
 W('矮','ǎi','เตี้ย','อ่าย','矢 (ลูกธนู) + 委 · ตรงข้ามกับ 高','我弟弟比我矮。','Wǒ dì|di bǐ wǒ ǎi.','น้องชายฉันเตี้ยกว่าฉัน'),
 W('胖','pàng','อ้วน','ผั่ง','月 (เนื้อ) ซ้าย + 半 · เนื้อเยอะ · ใช้ระวังเวลาพูดกับคนจริง ๆ','那个孩子很胖。','Nà ge hái|zi hěn pàng.','เด็กคนนั้นอ้วนมาก'),
 W('瘦','shòu','ผอม','โซ่ว','疒 (ป่วย) ด้านใน + 叟 · ผอมเกินไปเหมือนเพิ่งป่วย','你太瘦了，要多吃。','Nǐ tài shòu le, yào duō chī.','คุณผอมไป ต้องกินเยอะ ๆ'),
 W('慢','màn','ช้า','หม่าน','忄 (ใจ) ซ้าย + 曼 · ใจยังไม่รีบ = ช้า · ตรงข้ามกับ 快','他很慢，我很快。','Tā hěn màn, wǒ hěn kuài.','เขาช้า ฉันเร็ว'),
 W('重','zhòng','หนัก','จ้ง','ตัวช่วยจำ: คนยืนบนของทำให้หนัก · อ่าน zhòng เมื่อแปลว่าหนัก','这个杯子很重。','Zhè|ge bēi|zi hěn zhòng.','แก้วใบนี้หนักมาก'),
 W('容易','róng|yì','ง่าย','หร๋ง-อี้','容 (ยอม) + 易 (ง่าย) · ตรงข้ามกับ 难','这个字很容易。','Zhè|ge zì hěn róng|yì.','ตัวอักษรนี้ง่ายมาก'),
 W('难','nán','ยาก','หนั๋น','又 (อีก) + 隹 (นก) · ตัวช่วยจำ: จับนกยากมาก · ตรงข้ามกับ 容易','汉语不太难。','Hàn|yǔ bú tài nán.','ภาษาจีนไม่ยากมาก'),
 W('聪明','cōng|míng','ฉลาด','ชง-หมิ๋ง','听 (ฟัง) + 明 (ชัด) ตัวช่วยจำ: ฟังชัดและเข้าใจเร็ว','你的孩子很聪明。','Nǐ de hái|zi hěn cōng|míng.','ลูกคุณฉลาดมาก'),
 W('努力','nǔ|lì','ขยัน / พยายาม','หนู่-ลี่','努 (ออกแรง) + 力 (แรง) · ใช้ชมคนที่พยายาม','你学习很努力。','Nǐ xué|xí hěn nǔ|lì.','คุณเรียนขยันมาก')],
 sents:[['他/比/我/高。','tā/bǐ/wǒ/gāo.','เขาสูงกว่าฉัน'],['我/和/他/一样/大。','wǒ/hé/tā/yí|yàng/dà.','ฉันกับเขาใหญ่เท่ากัน'],['这/个/最/好吃。','zhè/ge/zuì/hǎo|chī.','อันนี้อร่อยที่สุด'],['今天/比/昨天/更/冷。','jīn|tiān/bǐ/zuó|tiān/gèng/lěng.','วันนี้หนาวกว่าเมื่อวานอีก'],['汉语/不/太/难。','Hàn|yǔ/bú/tài/nán.','ภาษาจีนไม่ยากมาก'],['你/学习/非常/努力。','nǐ/xué|xí/fēi|cháng/nǔ|lì.','คุณเรียนขยันมาก']],
 dlg:[['t','你比你哥哥高吗？','nǐ bǐ nǐ gē|ge gāo ma?','คุณสูงกว่าพี่ชายไหม'],['f','不，他比我高。','bù, tā bǐ wǒ gāo.','ไม่ เขาสูงกว่าฉัน'],['t','汉语难吗？','Hàn|yǔ nán ma?','ภาษาจีนยากไหม'],['f','不太难，我非常喜欢。','bú tài nán, wǒ fēi|cháng xǐ|huan.','ไม่ยากมาก ฉันชอบมาก']],
 rq:{p:2,wrong:[['带了，行李也准备好了。','dài le, xíng|li yě zhǔn|bèi hǎo le.','เอามาแล้ว กระเป๋าก็เตรียมเสร็จแล้ว'],['我小时候住在奶奶家，后来搬到了城市。','Wǒ xiǎo|shí|hou zhù zài nǎi|nai jiā, hòu|lái bān dào le chéng|shì.','ตอนเด็กฉันอยู่บ้านยาย ต่อมาก็ย้ายเข้าเมือง']]}},
{id:17,th:'สั่งอาหารในร้าน',zh:'点菜',chapter:202,emoji:'🧾',
 story:'ลามะพาเพื่อนไปร้านอาหารจีนจริง ๆ ครั้งแรก ต้องบอกจำนวนคน ขอเมนู สั่งอาหาร ขอไม่เผ็ด แล้วเรียกเช็คบิลให้เป็น',
 words:[
 W('欢迎','huān|yíng','ยินดีต้อนรับ','ฮวน-อิ๋ง','欢 เคยเจอใน 喜欢 · 迎 = ต้อนรับ','欢迎你来我家。','Huān|yíng nǐ lái wǒ jiā.','ยินดีต้อนรับสู่บ้านของฉัน'),
 W('欢迎光临','huān|yíng guāng|lín','ยินดีต้อนรับ (พนักงานพูด)','ฮวน-อิ๋ง กวง-หลิน','ประโยคที่พนักงานทักลูกค้าทุกร้าน · 光临 = มาเยือน','欢迎光临，请进。','Huān|yíng guāng|lín, qǐng jìn.','ยินดีต้อนรับ เชิญเข้ามาค่ะ'),
 W('几位','jǐ wèi','กี่ท่าน','จี่-เว่ย','几 (กี่) + 位 (ท่าน ตัวนับคนแบบสุภาพ)','你们几位？','Nǐ|men jǐ wèi?','พวกคุณกี่ท่าน'),
 W('服务员','fú|wù|yuán','พนักงานเสิร์ฟ','ฝู๋-อู้-หยวน','服务 (บริการ) + 员 (สมาชิก/พนักงาน) · ใช้เรียกพนักงานได้เลย','服务员，请来一下。','Fú|wù|yuán, qǐng lái yí|xià.','พนักงานคะ ขอเรียกหน่อย'),
 W('菜单','cài|dān','เมนู','ไช่-ตาน','菜 (อาหาร) + 单 (รายการ) = รายการอาหาร','请给我菜单。','Qǐng gěi wǒ cài|dān.','ขอเมนูหน่อย'),
 W('点菜','diǎn cài','สั่งอาหาร','เตี่ยน-ไช่','点 (จิ้ม/สั่ง) + 菜 · ใช้ในร้านอาหาร ตัวเดียวกับ 点 ที่เป็นโมง','我们现在点菜。','Wǒ|men xiàn|zài diǎn cài.','เราสั่งอาหารตอนนี้'),
 W('汤','tāng','ซุป','ทัง','氵 (น้ำ) ด้านซ้าย · ซุปในอาหารจีนมักกินระหว่างมื้อ','我要一个汤。','Wǒ yào yí ge tāng.','ฉันเอาซุปหนึ่งที่'),
 W('碗','wǎn','ชาม','หว่าน','ตัวนับและชื่อสิ่งของ: 一碗米饭 = ข้าวหนึ่งชาม','请来一碗米饭。','Qǐng lái yì wǎn mǐ|fàn.','ขอข้าวหนึ่งชาม'),
 W('筷子','kuài|zi','ตะเกียบ','ไคว่-จึ','竹 (ไผ่) ข้างบน เพราะตะเกียบเดิมทำจากไม้ไผ่ · 子 ท้ายคำเบา','我不会用筷子。','Wǒ bú huì yòng kuài|zi.','ฉันใช้ตะเกียบไม่เป็น'),
 W('不要','bú yào','ไม่เอา / อย่า','ปู๋-เย่า','不 + 要 · 不 เปลี่ยนเป็นเสียง 2 ก่อนเสียง 4 · ใช้ปฏิเสธหรือห้าม','我不要辣。','Wǒ bú yào là.','ฉันไม่เอาเผ็ด'),
 W('不用','bú yòng','ไม่ต้อง','ปู๋-ยง','用 (ใช้) · ปฏิเสธอย่างสุภาพ เช่น 不用谢 (ไม่ต้องขอบคุณ)','不用了，谢谢。','Bú yòng le, xiè|xie.','ไม่ต้องค่ะ ขอบคุณ'),
 W('还','hái','ยัง / อีก / ...ด้วย','ไห๋','ใช้เสริม “ยังมีอีก” 我还要 = ฉันยังอยากได้อีก · อ่านแบบนี้เมื่อแปลว่า ยัง (อีกเสียง huán = คืน)','你还要什么？','Nǐ hái yào shén|me?','คุณยังเอาอะไรอีก'),
 W('给','gěi','ให้ / แก่','เก่ย์','ใช้ “ให้” ได้ทั้งการยื่นของและบอกผู้รับ เช่น 给我 = ให้ฉัน · เป็นคำสำคัญสำหรับขอของ','请给我水。','Qǐng gěi wǒ shuǐ.','ขอน้ำให้ฉันหน่อย'),
 W('一共','yí|gòng','ทั้งหมด','อี๋-ก้ง','一 + 共 (รวม) · ใช้ตอนรวมราคา','一共多少钱？','Yí|gòng duō|shao qián?','รวมทั้งหมดเท่าไร'),
 W('打包','dǎ|bāo','ห่อกลับบ้าน','ต่า-เปา','打 + 包 (ห่อ) · ใช้เมื่อกินไม่หมดและขอห่อกลับ','我要打包。','Wǒ yào dǎ|bāo.','ฉันขอห่อกลับ'),
 W('买单','mǎi dān','เช็คบิล','ไหม่-ตาน','买 (จ่าย/ซื้อ) + 单 (ใบรายการ) · ตะโกนเรียกในร้านอาหารจีน','服务员，买单！','Fú|wù|yuán, mǎi dān!','พนักงาน เช็คบิลด้วย')],
 sents:[['欢迎/光临，/几/位？','huān|yíng/guāng|lín,/jǐ/wèi?','ยินดีต้อนรับ กี่ท่านคะ'],['请/给/我/菜单。','qǐng/gěi/wǒ/cài|dān.','ขอเมนูให้ฉันหน่อย'],['我/要/一/碗/米饭。','wǒ/yào/yì/wǎn/mǐ|fàn.','ฉันเอาข้าวหนึ่งชาม'],['我/不/要/辣。','wǒ/bú/yào/là.','ฉันไม่เอาเผ็ด'],['一共/多少/钱？','yí|gòng/duō|shao/qián?','รวมทั้งหมดเท่าไร'],['服务员，/买单。','fú|wù|yuán,/mǎi dān.','พนักงาน เช็คบิลด้วย']],
 dlg:[['t','欢迎光临，几位？','huān|yíng guāng|lín, jǐ wèi?','ยินดีต้อนรับ กี่ท่านคะ'],['f','三位，请给我菜单。','sān wèi, qǐng gěi wǒ cài|dān.','สามท่าน ขอเมนูด้วย'],['t','你们想吃什么？','nǐ|men xiǎng chī shén|me?','พวกคุณอยากกินอะไร'],['f','一个鱼，一个汤，不要辣。','yí ge yú, yí ge tāng, bú yào là.','ปลาหนึ่ง ซุปหนึ่ง ไม่เผ็ดครับ']],
 rq:{p:0,wrong:[['我要两根油条，一杯豆浆。','Wǒ yào liǎng gēn yóu|tiáo, yì bēi dòu|jiāng.','ขอปาท่องโก๋สองชิ้นกับน้ำเต้าหู้หนึ่งแก้ว'],['很安静，也很方便。','hěn ān|jìng, yě hěn fāng|biàn.','เงียบดีและสะดวกด้วย']]}},
{id:19,th:'ถามทางและบอกทิศ',zh:'在哪儿',chapter:203,emoji:'🧭',
 story:'ลามะหลงทางในเมืองใหญ่! ต้องถามคนว่าธนาคารอยู่ไหน ซุปเปอร์ใกล้แค่ไหน แล้วฟังให้เข้าใจว่าให้เลี้ยวซ้ายหรือขวา เดินตรงไปอีกเท่าไร',
 words:[
 W('左边','zuǒ|bian','ด้านซ้าย','จั่ว-เปียน','左 (ซ้าย) + 边 (ด้าน) · พยางค์หลังเสียงเบา','银行在左边。','Yín|háng zài zuǒ|bian.','ธนาคารอยู่ทางซ้าย'),
 W('右边','yòu|bian','ด้านขวา','โย่ว-เปียน','右 (ขวา) + 边 · ตัวช่วยจำ: ขวามือใช้ถือตะเกียบ (口 ปาก อยู่ข้างล่าง)','商店在右边。','Shāng|diàn zài yòu|bian.','ร้านอยู่ทางขวา'),
 W('旁边','páng|biān','ข้าง ๆ','ผาง-เปียน','旁 (ข้าง) + 边 · พยางค์หลังเสียง 1 เต็มเสียง','我家在学校旁边。','Wǒ jiā zài xué|xiào páng|biān.','บ้านฉันอยู่ข้างโรงเรียน'),
 W('对面','duì|miàn','ฝั่งตรงข้าม','ตุ้ย-เมี่ยน','对 (หันหน้าเข้า) + 面 (ด้านหน้า) = ด้านที่หันหน้าเข้าหากัน','医院在学校对面。','Yī|yuàn zài xué|xiào duì|miàn.','โรงพยาบาลอยู่ตรงข้ามโรงเรียน'),
 W('外面','wài|miàn','ข้างนอก','ว่าย-เมี่ยน','外 (นอก) + 面 · ตรงข้ามกับ 里面 (ข้างใน)','外面很冷。','Wài|miàn hěn lěng.','ข้างนอกหนาวมาก'),
 W('附近','fù|jìn','บริเวณใกล้เคียง','ฟู่-จิ้น','附 (ติดกับ) + 近 (ใกล้) · ใช้ถามร้านใกล้ ๆ','附近有商店吗？','Fù|jìn yǒu shāng|diàn ma?','แถวนี้มีร้านค้าไหม'),
 W('往','wǎng','ไปทาง / มุ่งไป','หว่าง','往 + ทิศ + กริยา เช่น 往前走 = เดินไปข้างหน้า','请往右走。','Qǐng wǎng yòu zǒu.','กรุณาเดินไปทางขวา'),
 W('中间','zhōng|jiān','ตรงกลาง / ระหว่าง','จง-เจียน','中 (กลาง) + 间 (ช่อง/ระหว่าง) = ตรงกลาง · ใช้บอกตำแหน่งระหว่างสองสิ่ง','银行在超市和医院中间。','Yín|háng zài chāo|shì hé yī|yuàn zhōng|jiān.','ธนาคารอยู่ระหว่างซูเปอร์กับโรงพยาบาล'),
 W('一直','yì|zhí','ตรงไปเรื่อย ๆ','อี้-จื๋อ','一 (หนึ่ง) + 直 (ตรง) = ตรงไปทางเดียว · 一 เปลี่ยนเป็นเสียง 4 ก่อนเสียง 2','一直走，不要拐。','Yì|zhí zǒu, bú yào guǎi.','เดินตรงไป อย่าเลี้ยว'),
 W('东','dōng','ทิศตะวันออก','ตง','ใช้เรียงกับ 南 西 北 บอกทิศ · ใช้ต่อ 边 เป็น 东边 = ด้านตะวันออก','学校在公园的东边。','Xué|xiào zài gōng|yuán de dōng|bian.','โรงเรียนอยู่ทางตะวันออกของสวน'),
 W('怎么走','zěn|me zǒu','ไปอย่างไร','เจิ่น-เมอ-โจ่ว','怎么 + 走 · ใช้ถามทางสั้น ๆ ที่สุด','请问，银行怎么走？','Qǐng wèn, yín|háng zěn|me zǒu?','ขอถามหน่อย ไปธนาคารไปอย่างไร'),
 W('迷路','mí lù','หลงทาง','หมี๋-ลู่','迷 (หลง) + 路 (ทาง) · เจอ 路 แล้วในบทก่อน','对不起，我迷路了。','Duì|bu|qǐ, wǒ mí lù le.','ขอโทษ ฉันหลงทาง'),
 W('公园','gōng|yuán','สวนสาธารณะ','กง-หยวน','公 (สาธารณะ) + 园 (สวน) · 公 เจอใน 公共汽车','我们去公园吧。','Wǒ|men qù gōng|yuán ba.','เราไปสวนสาธารณะกันเถอะ'),
 W('银行','yín|háng','ธนาคาร','อิ๋น-หาง','银 (เงิน) + 行 (แถว/หน่วยงาน) · 行 ตัวนี้อ่าน háng ไม่ใช่ xíng','银行在哪儿？','Yín|háng zài nǎ|r?','ธนาคารอยู่ที่ไหน'),
 W('超市','chāo|shì','ซูเปอร์มาร์เก็ต','เชา-ชื่อ','超 (เหนือ) + 市 (ตลาด) = ตลาดขนาดใหญ่','超市在公园旁边。','Chāo|shì zài gōng|yuán páng|biān.','ซูเปอร์มาร์เก็ตอยู่ข้างสวน'),
 W('地图','dì|tú','แผนที่','ตี้-ทู๋','地 (พื้นที่) + 图 (ภาพ) = ภาพของพื้นที่','你有地图吗？','Nǐ yǒu dì|tú ma?','คุณมีแผนที่ไหม')],
 sents:[['请问，/银行/在/哪儿？','qǐng wèn,/yín|háng/zài/nǎ|r?','ขอถามหน่อย ธนาคารอยู่ไหน'],['银行/在/超市/旁边。','yín|háng/zài/chāo|shì/páng|biān.','ธนาคารอยู่ข้างซูเปอร์'],['银行/在/超市/和/医院/中间。','yín|háng/zài/chāo|shì/hé/yī|yuàn/zhōng|jiān.','ธนาคารอยู่ระหว่างซูเปอร์กับโรงพยาบาล'],['公园/在/医院/对面。','gōng|yuán/zài/yī|yuàn/duì|miàn.','สวนอยู่ตรงข้ามโรงพยาบาล'],['我/迷路/了，/有/地图/吗？','wǒ/mí lù/le,/yǒu/dì|tú/ma?','ฉันหลงทาง มีแผนที่ไหม'],['附近/有/超市/吗？','fù|jìn/yǒu/chāo|shì/ma?','แถวนี้มีซูเปอร์ไหม']],
 dlg:[['t','请问，银行怎么走？','qǐng wèn, yín|háng zěn|me zǒu?','ขอถามหน่อย ไปธนาคารไปอย่างไร'],['f','你一直走，银行在右边。','nǐ yì|zhí zǒu, yín|háng zài yòu|bian.','เดินตรงไป ธนาคารอยู่ทางขวา'],['t','离这儿远吗？','lí zhè|r yuǎn ma?','ไกลจากที่นี่ไหม'],['f','不远，很近。','bù yuǎn, hěn jìn.','ไม่ไกล ใกล้มาก']],
 rq:{p:2,wrong:[['一杯珍珠奶茶，大杯，少糖去冰。','Yì bēi zhēn|zhū nǎi|chá, dà bēi, shǎo táng qù bīng.','ชานมไข่มุกหนึ่งแก้ว แก้วใหญ่ หวานน้อยไม่ใส่น้ำแข็ง'],['别着急，我会打电话告诉你。','Bié zháo|jí, wǒ huì dǎ diàn|huà gào|su nǐ.','อย่าร้อนใจ ฉันจะโทรไปบอกคุณ']]}},
{id:24,th:'ที่ทำงานและการสอบ',zh:'工作和考试',chapter:11,emoji:'💼',
 story:'ลามะเริ่มทำงานพาร์ตไทม์ที่บริษัทแห่งหนึ่งและต้องสอบวัดระดับพร้อมกัน ต้องคุยกับหัวหน้า ประชุม ขอความช่วยเหลือ และเตรียมสอบให้ทัน',
 words:[
 W('公司','gōng|sī','บริษัท','กง-ซือ','公 (ส่วนรวม) + 司 (ดูแล/แผนก) = องค์กรที่ทำงานร่วมกัน','我在一家大公司工作。','Wǒ zài yì jiā dà gōng|sī gōng|zuò.','ฉันทำงานที่บริษัทใหญ่แห่งหนึ่ง'),
 W('经理','jīng|lǐ','ผู้จัดการ','จิง-หลี่','经 (ผ่าน/บริหาร) + 理 (จัดการ)','经理今天不在公司。','Jīng|lǐ jīn|tiān bú zài gōng|sī.','วันนี้ผู้จัดการไม่อยู่ที่บริษัท'),
 W('同事','tóng|shì','เพื่อนร่วมงาน','ถ๋ง-ชื่อ','同 (ร่วม) + 事 (งาน) · 同 เจอใน 同学','我的同事都很好。','Wǒ de tóng|shì dōu hěn hǎo.','เพื่อนร่วมงานของฉันดีทุกคน'),
 W('办公室','bàn|gōng|shì','ห้องทำงาน / ออฟฟิศ','ปั้น-กง-ชื่อ','办公 (ทำงานธุรการ) + 室 (ห้อง)','经理在办公室里。','Jīng|lǐ zài bàn|gōng|shì lǐ.','ผู้จัดการอยู่ในห้องทำงาน'),
 W('会议','huì|yì','การประชุม','ฮุ่ย-อี้','会 (ชุมนุม) + 议 (ปรึกษา) · 讠 ซ้ายเกี่ยวกับการพูดคุย','下午三点有一个会议。','Xià|wǔ sān diǎn yǒu yí ge huì|yì.','บ่ายสามมีประชุมหนึ่งครั้ง'),
 W('问题','wèn|tí','คำถาม / ปัญหา','เวิ่น-ถี๋','问 (ถาม) + 题 (หัวข้อ) = เรื่องที่ต้องถามหรือแก้ · ใช้ได้ทั้งคำถามและปัญหา','我有一个问题。','Wǒ yǒu yí ge wèn|tí.','ฉันมีคำถามหนึ่งข้อ'),
 W('帮助','bāng|zhù','ช่วยเหลือ','ปาง-จู้','帮 (ช่วย) + 助 (ช่วย) สองคำความหมายเดียวกันมาประกอบกัน','谢谢你帮助我。','Xiè|xie nǐ bāng|zhù wǒ.','ขอบคุณที่ช่วยฉัน'),
 W('作业','zuò|yè','การบ้าน','จั้ว-เย่','作 (ทำ) + 业 (งาน/กิจ) = งานที่ต้องทำ','今天的作业很多。','Jīn|tiān de zuò|yè hěn|duō.','การบ้านวันนี้เยอะมาก'),
 W('考试','kǎo|shì','สอบ / การสอบ','เข่า-ชื่อ','考 (ตรวจสอบ) + 试 (ลอง) · 试 เจอใน HSK2 บท 22','明天我有汉语考试。','Míng|tiān wǒ yǒu Hàn|yǔ kǎo|shì.','พรุ่งนี้ฉันมีสอบภาษาจีน'),
 W('成绩','chéng|jì','ผลการเรียน / คะแนน','เฉิง-จี้','成 (สำเร็จ) + 绩 (ผลงาน) = ผลที่สำเร็จ','他的成绩非常好。','Tā de chéng|jì fēi|cháng hǎo.','ผลการเรียนของเขาดีมาก'),
 W('复习','fù|xí','ทบทวนบทเรียน','ฟู่-สี๋','复 (ซ้ำ) + 习 (ฝึก) · 习 เจอใน 学习','考试以前要认真复习。','Kǎo|shì yǐ|qián yào rèn|zhēn fù|xí.','ก่อนสอบต้องทบทวนอย่างตั้งใจ'),
 W('准备','zhǔn|bèi','เตรียม / เตรียมพร้อม','จุ่น-เป้ย','准 (แน่นอน) + 备 (พร้อม) · 准 อ่าน zhǔn','我在准备明天的会议。','Wǒ zài zhǔn|bèi míng|tiān de huì|yì.','ฉันกำลังเตรียมประชุมพรุ่งนี้'),
 W('机会','jī|huì','โอกาส','จี-ฮุ่ย','ตัวช่วยจำ: 机 (จังหวะ) + 会 (ได้พบ) = จังหวะที่ได้เจอ','这是一个很好的机会。','Zhè shì yí ge hěn hǎo de jī|huì.','นี่เป็นโอกาสที่ดีมาก'),
 W('经验','jīng|yàn','ประสบการณ์','จิง-เย่น','经 (ผ่าน) + 验 (ทดสอบ) = สิ่งที่ผ่านและพิสูจน์มาแล้ว','她有很多工作经验。','Tā yǒu hěn|duō gōng|zuò jīng|yàn.','เธอมีประสบการณ์ทำงานมาก'),
 W('需要','xū|yào','ต้องการ / จำเป็นต้อง','ซวี-เย่า','需 (ต้อง) + 要 (อยากได้) · ใช้กับสิ่งที่จำเป็นจริง ๆ','你需要我帮忙吗？','Nǐ xū|yào wǒ bāng máng ma?','คุณต้องการให้ฉันช่วยไหม'),
 W('忙','máng','ยุ่ง','หมั๋ง','忄 (ใจ) + 亡 (หายไป) ตัวช่วยจำ: ยุ่งจนใจหายไปไหนไม่รู้','我最近很忙。','Wǒ zuì|jìn hěn máng.','ช่วงนี้ฉันยุ่งมาก')],
 sents:[['我/在/一/家/公司/工作。','wǒ/zài/yì/jiā/gōng|sī/gōng|zuò.','ฉันทำงานที่บริษัทแห่งหนึ่ง'],['经理/下午/有/会议。','jīng|lǐ/xià|wǔ/yǒu/huì|yì.','ผู้จัดการมีประชุมตอนบ่าย'],['我/需要/你/的/帮助。','wǒ/xū|yào/nǐ/de/bāng|zhù.','ฉันต้องการความช่วยเหลือของคุณ'],['明天/有/考试，/我/要/复习。','míng|tiān/yǒu/kǎo|shì,/wǒ/yào/fù|xí.','พรุ่งนี้มีสอบ ฉันต้องทบทวน'],['这/个/问题/不/容易。','zhè/ge/wèn|tí/bù/róng|yì.','ปัญหานี้ไม่ง่าย'],['我/最近/很/忙，/没/有/时间。','wǒ/zuì|jìn/hěn/máng,/méi/yǒu/shí|jiān.','ช่วงนี้ฉันยุ่ง ไม่มีเวลา']],
 dlg:[['t','你准备好考试了吗？','nǐ zhǔn|bèi hǎo kǎo|shì le ma?','คุณเตรียมสอบพร้อมหรือยัง'],['f','还没有，我需要再复习一下。','hái méi yǒu, wǒ xū|yào zài fù|xí yí|xià.','ยังเลย ต้องทบทวนอีกหน่อย'],['t','你有问题可以问我。','nǐ yǒu wèn|tí kě|yǐ wèn wǒ.','ถ้ามีคำถามถามฉันได้'],['f','谢谢你的帮助！','xiè|xie nǐ de bāng|zhù!','ขอบคุณที่ช่วยนะ']],
 rq:{p:2,wrong:[['因为我想做自己喜欢的事。','Yīn|wèi wǒ xiǎng zuò zì|jǐ xǐ|huan de shì.','เพราะฉันอยากทำสิ่งที่ตัวเองชอบ'],['我要去养老院当义工。','Wǒ yào qù yǎng|lǎo|yuàn dāng yì|gōng.','ฉันจะไปเป็นจิตอาสาที่บ้านพักคนชรา']]}},
{id:25,th:'ความรู้สึกและความหวัง',zh:'心情',chapter:11,emoji:'💭',
 story:'วันสอบมาถึงแล้ว! ลามะทั้งตื่นเต้น ทั้งกังวล แต่ก็ยังหวังว่าจะทำได้ ต้องเล่าความรู้สึกให้เพื่อนฟังและอธิบายเหตุผลด้วยคำเชื่อมใหม่ ๆ',
 words:[
 W('担心','dān|xīn','กังวล','ตัน-ซิน','担 (แบก) + 心 (ใจ) = แบกไว้ในใจ','我很担心明天的考试。','Wǒ hěn dān|xīn míng|tiān de kǎo|shì.','ฉันกังวลเรื่องสอบพรุ่งนี้มาก'),
 W('生气','shēng qì','โกรธ','เซิง-ชี่','生 (เกิด) + 气 (ลมหายใจ/อารมณ์) = อารมณ์พลุ่ง','别生气，好吗？','Bié shēng qì, hǎo ma?','อย่าโกรธนะ ได้ไหม'),
 W('害怕','hài|pà','กลัว','ไฮ่-ผ่า','害 (ทำร้าย) + 怕 (กลัว) · 忄 (ใจ) ซ้ายของ 怕','我有点儿害怕。','Wǒ yǒu diǎn|r hài|pà.','ฉันกลัวนิด ๆ'),
 W('难过','nán|guò','เสียใจ','หนั๋น-กั้ว','难 (ยาก) + 过 (ผ่าน) = ผ่านไปยาก','听到这个消息，我很难过。','Tīng dào zhè|ge xiāo|xi, wǒ hěn nán|guò.','ได้ยินข่าวนี้แล้วฉันเสียใจมาก'),
 W('激动','jī|dòng','ตื่นเต้น / ซาบซึ้ง','จี-ต้ง','激 (กระตุ้น) + 动 (ขยับ) = ใจเต้นแรง','比赛以前，大家都很激动。','Bǐ|sài yǐ|qián, dà|jiā dōu hěn jī|dòng.','ก่อนแข่งทุกคนตื่นเต้นมาก'),
 W('满意','mǎn|yì','พอใจ','หม่าน-อี้','满 (เต็ม) + 意 (ใจ) = ใจเต็ม','我对成绩很满意。','Wǒ duì chéng|jì hěn mǎn|yì.','ฉันพอใจกับผลสอบมาก'),
 W('关心','guān|xīn','ใส่ใจ / ห่วงใย','กวน-ซิน','关 (เกี่ยวข้อง) + 心 (ใจ)','谢谢你关心我。','Xiè|xie nǐ guān|xīn wǒ.','ขอบคุณที่ห่วงใยฉัน'),
 W('习惯','xí|guàn','ความเคยชิน / ชิน','สี๋-กั้น','习 (ฝึก) + 惯 (เคย) = ฝึกจนเคย','我已经习惯了这里的天气。','Wǒ yǐ|jīng xí|guàn le zhè|lǐ de tiān|qì.','ฉันชินกับอากาศที่นี่แล้ว'),
 W('相信','xiāng|xìn','เชื่อ / ไว้ใจ','เซียง-ซิ่น','相 (ซึ่งกันและกัน) + 信 (เชื่อ) · 亻 ซ้ายเกี่ยวกับคน','我相信你能做好。','Wǒ xiāng|xìn nǐ néng zuò hǎo.','ฉันเชื่อว่าคุณทำได้ดี'),
 W('希望','xī|wàng','หวัง / ความหวัง','ซี-หว่าง','希 (หวังไกล) + 望 (มองไกล) · ใช้ได้ทั้งคำกริยาและคำนาม','我希望你明天来。','Wǒ xī|wàng nǐ míng|tiān lái.','ฉันหวังว่าพรุ่งนี้คุณจะมา'),
 W('愿意','yuàn|yì','เต็มใจ','เย่วียน-อี้','愿 (ปรารถนา) + 意 (ใจ) · ใช้บอกว่ายินดีทำ','我愿意帮你。','Wǒ yuàn|yì bāng nǐ.','ฉันยินดีช่วยคุณ'),
 W('其实','qí|shí','ที่จริงแล้ว','ฉี๋-สื๋อ','其 (นั้น) + 实 (จริง) = เรื่องจริงคือ…','其实我不太累。','Qí|shí wǒ bú tài lèi.','ที่จริงฉันไม่ค่อยเหนื่อย'),
 W('突然','tū|rán','ทันใดนั้น','ทู-หราน','突 (พรวด) + 然 (เช่นนั้น) = เกิดขึ้นเฉียบพลัน','天气突然变冷了。','Tiān|qì tū|rán biàn lěng le.','อากาศเปลี่ยนหนาวขึ้นทันที'),
 W('终于','zhōng|yú','ในที่สุด','จง-หยู๋','终 (จบ) + 于 (ที่) = ถึงจุดจบแล้ว · ใช้เมื่อรอมานาน','我终于考完了！','Wǒ zhōng|yú kǎo wán le!','ในที่สุดฉันก็สอบเสร็จ'),
 W('虽然','suī|rán','แม้ว่า','ซุย-หราน','ใช้คู่กับ 但是 / 可是: 虽然…但是… แม้ว่า…แต่…','虽然很累，但是很开心。','Suī|rán hěn lèi, dàn|shì hěn kāi|xīn.','แม้เหนื่อยแต่ก็มีความสุข'),
 W('但是','dàn|shì','แต่','ตั้น-ชื่อ','เชื่อมประโยคที่ขัดแย้ง · ใช้บ่อยกับ 虽然','我想去，但是没有时间。','Wǒ xiǎng qù, dàn|shì méi yǒu shí|jiān.','ฉันอยากไปแต่ไม่มีเวลา')],
 sents:[['我/有/点儿/担心。','wǒ/yǒu/diǎn|r/dān|xīn.','ฉันกังวลนิดหน่อย'],['虽然/很/累，/但是/很/开心。','suī|rán/hěn/lèi,/dàn|shì/hěn/kāi|xīn.','แม้เหนื่อยแต่มีความสุข'],['我/终于/考完/了。','wǒ/zhōng|yú/kǎo wán/le.','ในที่สุดฉันก็สอบเสร็จ'],['其实/我/很/满意。','qí|shí/wǒ/hěn/mǎn|yì.','ที่จริงฉันพอใจมาก'],['我/相信/你/能/做/好。','wǒ/xiāng|xìn/nǐ/néng/zuò/hǎo.','ฉันเชื่อว่าคุณทำได้'],['希望/明天/天气/好。','xī|wàng/míng|tiān/tiān|qì/hǎo.','หวังว่าพรุ่งนี้อากาศดี']],
 dlg:[['t','你今天怎么样？','nǐ jīn|tiān zěn|me|yàng?','วันนี้คุณเป็นอย่างไรบ้าง'],['f','我有点儿担心，但是也很激动。','wǒ yǒu diǎn|r dān|xīn, dàn|shì yě hěn jī|dòng.','ฉันกังวลนิดหน่อยแต่ก็ตื่นเต้นด้วย'],['t','别担心，我相信你。','bié dān|xīn, wǒ xiāng|xìn nǐ.','อย่ากังวล ฉันเชื่อมั่นในตัวคุณ'],['f','谢谢你关心我。','xiè|xie nǐ guān|xīn wǒ.','ขอบคุณที่ห่วงใยฉัน']],
 rq:{p:2,wrong:[['我最喜欢女主角，她的表演很自然。','Wǒ zuì xǐ|huan nǚ|zhǔ|jué, tā de biǎo|yǎn hěn zì|rán.','ฉันชอบนางเอกที่สุด การแสดงของเธอเป็นธรรมชาติมาก'],['你买三个，我给你包邮。','Nǐ mǎi sān ge, wǒ gěi nǐ bāo|yóu.','คุณซื้อสามชิ้น ฉันส่งฟรีให้']]}},
{id:26,th:'เมือง ฤดูกาล และการเดินทางไกล',zh:'城市和季节',chapter:11,emoji:'🌆',
 story:'หลังสอบเสร็จ ลามะเที่ยวเมืองใหญ่กับเพื่อน เจอรถติด ฟังเรื่องสี่ฤดูของจีน และชมวิวสวย ๆ ระหว่างทาง',
 words:[
 W('城市','chéng|shì','เมือง','เฉิง-ชื่อ','城 (กำแพงเมือง) + 市 (ตลาด) = เมืองที่มีตลาด','这个城市很大。','Zhè|ge chéng|shì hěn dà.','เมืองนี้ใหญ่มาก'),
 W('环境','huán|jìng','สิ่งแวดล้อม','หวน-จิ้ง','环 (วงล้อม) + 境 (ขอบเขต) = สิ่งที่ล้อมรอบเรา','这里的环境很好。','Zhè|lǐ de huán|jìng hěn hǎo.','สิ่งแวดล้อมที่นี่ดีมาก'),
 W('宾馆','bīn|guǎn','โรงแรมเล็ก / เกสต์เฮาส์','ปิน-กว่าน','宾 (แขก) + 馆 (อาคารให้บริการ) = ที่พักสำหรับแขก · ใช้กับโรงแรมขนาดเล็กถึงกลาง','我们住在火车站旁边的宾馆。','Wǒ|men zhù zài huǒ|chē|zhàn páng|biān de bīn|guǎn.','เราพักที่โรงแรมข้างสถานีรถไฟ'),
 W('交通','jiāo|tōng','การจราจร','เจียว-ทง','交 (ตัดกัน) + 通 (ผ่าน) = ถนนที่สัญจรผ่านกัน','这个城市的交通很方便。','Zhè|ge chéng|shì de jiāo|tōng hěn fāng|biàn.','การจราจรในเมืองนี้สะดวกมาก'),
 W('堵车','dǔ chē','รถติด','ตู่-เช่อ','堵 (อุดตัน) + 车 (รถ) · 土 ซ้ายเหมือนดินอุดทาง','下班的时候总是堵车。','Xià bān de shí|hou zǒng|shì dǔ chē.','ตอนเลิกงานรถติดเสมอ'),
 W('行李箱','xíng|li|xiāng','กระเป๋าเดินทาง','สิง-หลี-เซียง','行李 (สัมภาระ) + 箱 (กล่อง/หีบ) · ใน 行李 ตัว 李 อ่านเสียงเบา','我的行李箱太重了。','Wǒ de xíng|li|xiāng tài zhòng le.','กระเป๋าเดินทางของฉันหนักเกินไป'),
 W('北方','běi|fāng','ทางเหนือ','เป่ย-ฟาง','北 (เหนือ) + 方 (ทิศทาง) · คู่กับ 南方 (ทางใต้)','北方的冬天很冷。','Běi|fāng de dōng|tiān hěn lěng.','ฤดูหนาวทางเหนือหนาวมาก'),
 W('地方','dì|fang','สถานที่','ตี้-ฟาง','地 (พื้นที่) + 方 (ด้าน) · คำที่สองอ่านเสียงเบา','这个地方很漂亮。','Zhè|ge dì|fang hěn piào|liang.','สถานที่นี้สวยมาก'),
 W('风景','fēng|jǐng','ทิวทัศน์','เฟิง-จิ่ง','风 (ลม) + 景 (ภาพ) = ภาพที่มีลมพัดผ่าน','这里的风景真漂亮。','Zhè|lǐ de fēng|jǐng zhēn piào|liang.','ทิวทัศน์ที่นี่สวยจริง ๆ'),
 W('季节','jì|jié','ฤดูกาล','จี้-เจี๋ย','季 (หนึ่งในสี่ช่วง) + 节 (ข้อ/ตอน)','你喜欢哪个季节？','Nǐ xǐ|huan nǎ ge jì|jié?','คุณชอบฤดูไหน'),
 W('春天','chūn|tiān','ฤดูใบไม้ผลิ','ชุน-เทียน','春 + 天 (ฟ้า/วัน) · ชุนเสียงคล้าย "ชุ่ม" ฝนฤดูแรก','春天来了，花开了。','Chūn|tiān lái le, huā kāi le.','ฤดูใบไม้ผลิมาแล้ว ดอกไม้บาน'),
 W('夏天','xià|tiān','ฤดูร้อน','เซี่ย-เทียน','夏 + 天 · 夏 เสียงคล้าย "เซี่ย" ร้อนจนเหงื่อซ่า','夏天很热。','Xià|tiān hěn rè.','ฤดูร้อนร้อนมาก'),
 W('秋天','qiū|tiān','ฤดูใบไม้ร่วง','ชิว-เทียน','秋 มี 禾 (ข้าว) ซ้าย + 火 (ไฟ) ขวา · ข้าวสุกสีไฟ','秋天不冷也不热。','Qiū|tiān bù lěng yě bú rè.','ฤดูใบไม้ร่วงไม่หนาวไม่ร้อน'),
 W('冬天','dōng|tiān','ฤดูหนาว','ตง-เทียน','冬 + 天 · เสียง "ตง" เหมือนตัวสั่นตงตง','冬天我想吃火锅。','Dōng|tiān wǒ xiǎng chī huǒ|guō.','ฤดูหนาวฉันอยากกินสุกี้หม้อไฟ'),
 W('世界','shì|jiè','โลก','ชื่อ-เจี้ย','世 (ชั่วอายุ) + 界 (ขอบเขต) = ขอบเขตของโลก','我想去世界各地旅行。','Wǒ xiǎng qù shì|jiè gè dì lǚ|xíng.','ฉันอยากไปเที่ยวทั่วโลก'),
 W('变化','biàn|huà','การเปลี่ยนแปลง','เปี้ยน-ฮั่ว','变 (เปลี่ยน) + 化 (กลายเป็น) · ใช้ได้ทั้งคำนามและกริยา','这几年城市的变化很大。','Zhè jǐ nián chéng|shì de biàn|huà hěn dà.','หลายปีมานี้เมืองเปลี่ยนไปมาก')],
 sents:[['这/个/城市/的/交通/很/方便。','zhè/ge/chéng|shì/de/jiāo|tōng/hěn/fāng|biàn.','การจราจรในเมืองนี้สะดวกมาก'],['下班/的/时候/总是/堵车。','xià bān/de/shí|hou/zǒng|shì/dǔ chē.','ตอนเลิกงานรถติดเสมอ'],['我/喜欢/春天，/因为/花/开/了。','wǒ/xǐ|huan/chūn|tiān,/yīn|wèi/huā/kāi/le.','ฉันชอบฤดูใบไม้ผลิเพราะดอกไม้บาน'],['这/里/的/风景/真/漂亮。','zhè/lǐ/de/fēng|jǐng/zhēn/piào|liang.','ทิวทัศน์ที่นี่สวยจริง ๆ'],['夏天/太/热，/冬天/太/冷。','xià|tiān/tài/rè,/dōng|tiān/tài/lěng.','ฤดูร้อนร้อนไป ฤดูหนาวหนาวไป'],['这/几/年/变化/很/大。','zhè/jǐ/nián/biàn|huà/hěn/dà.','หลายปีมานี้เปลี่ยนไปมาก']],
 dlg:[['t','你喜欢哪个季节？','nǐ xǐ|huan nǎ ge jì|jié?','คุณชอบฤดูไหน'],['f','我喜欢秋天，不冷也不热。','wǒ xǐ|huan qiū|tiān, bù lěng yě bú rè.','ฉันชอบฤดูใบไม้ร่วง ไม่หนาวไม่ร้อน'],['t','这个城市的秋天怎么样？','zhè|ge chéng|shì de qiū|tiān zěn|me|yàng?','ฤดูใบไม้ร่วงในเมืองนี้เป็นอย่างไร'],['f','风景很漂亮，就是有点儿堵车。','fēng|jǐng hěn piào|liang, jiù|shì yǒu diǎn|r dǔ chē.','ทิวทัศน์สวยแต่รถติดนิดหน่อย']],
 rq:{p:2,wrong:[['很方便，社区里还有公园，绿化也不错。','Hěn fāng|biàn, shè|qū lǐ hái yǒu gōng|yuán, lǜ|huà yě bú cuò.','สะดวกมาก ในชุมชนยังมีสวน และพื้นที่สีเขียวก็ดี'],['我每个月先做预算，再决定买什么。','Wǒ měi ge yuè xiān zuò yù|suàn, zài jué|dìng mǎi shén|me.','ฉันทำงบทุกเดือนก่อนแล้วค่อยตัดสินใจว่าจะซื้ออะไร']]}},
{id:58,th:'เล่าเรื่องวันวาน',zh:'美好的回忆',chapter:210,emoji:'📖',
 story:'ลามะเปิดอัลบั้มเก่าแล้วเล่าความทรงจำสมัยเด็กให้เพื่อนฟัง ทั้งเรื่องครั้งแรกที่ไม่มีวันลืม และวันที่ย้ายเข้าเมืองใหญ่',
 words:[
 W('以前','yǐ|qián','เมื่อก่อน','อี่-เฉียน','以 (ตั้งแต่) + 前 (ข้างหน้า) = ช่วงเวลาก่อนหน้านี้','我以前不喜欢吃辣。','Wǒ yǐ|qián bù xǐ|huan chī là.','เมื่อก่อนฉันไม่ชอบกินเผ็ด'),
 W('小时候','xiǎo|shí|hou','ตอนเด็ก','เสี่ยว-สือ-โฮ่ว','小 (เล็ก) + 时候 (ตอนที่) = ตอนที่ยังตัวเล็ก','小时候我常常和哥哥玩。','Xiǎo|shí|hou wǒ cháng|cháng hé gē|ge wán.','ตอนเด็กฉันมักเล่นกับพี่ชายบ่อยๆ'),
 W('记得','jì|de','จำได้','จี้-เต๋อ','记 (จดจำ) + 得 (ได้) = จำเก็บไว้ได้','你还记得她的名字吗？','Nǐ hái jì|de tā de míng|zi ma?','คุณยังจำชื่อเธอได้ไหม'),
 W('忘记','wàng|jì','ลืม','หวั่ง-จี้','忘 (ลืม) + 记 (จำ) = ลืมสิ่งที่เคยจำ','我忘记他的电话号码了。','Wǒ wàng|jì tā de diàn|huà hào|mǎ le.','ฉันลืมเบอร์โทรของเขาแล้ว'),
 W('第一次','dì|yī|cì','ครั้งแรก','ตี้-อี-ชื่อ','第 (ลำดับ) + 一 (หนึ่ง) + 次 (ครั้ง) = ลำดับที่หนึ่งของครั้ง','这是我第一次坐飞机。','Zhè shì wǒ dì|yī|cì zuò fēi|jī.','นี่เป็นครั้งแรกที่ฉันนั่งเครื่องบิน'),
 W('过去','guò|qù','ในอดีต / ผ่านไป','กั้ว-ชวี่','过 (ผ่าน) + 去 (ไป) · ใช้เล่าเรื่องในอดีตได้','过去我不会游泳。','Guò|qù wǒ bú huì yóu|yǒng.','ในอดีตฉันว่ายน้ำไม่เป็น'),
 W('后来','hòu|lái','ต่อมา','โฮ่ว-ไหล','后 (หลัง) + 来 (มา) = เวลาที่ตามมาภายหลัง','后来他搬到了北京。','Hòu|lái tā bān dào le Běi|jīng.','ต่อมาเขาย้ายไปอยู่ปักกิ่ง'),
 W('年轻','nián|qīng','หนุ่มสาว / อายุน้อย','เหนียน-ชิง','年 (ปี) + 轻 (เบา/น้อย) = อายุน้อย','年轻的时候，我住在小城。','Nián|qīng de shí|hou, wǒ zhù zài xiǎo chéng.','ตอนยังหนุ่มสาว ฉันอยู่ในเมืองเล็ก ๆ'),
 W('故事','gù|shi','เรื่องเล่า','กู้-ชื่อ','故 (เก่า) + 事 (เรื่อง) = เรื่องเก่าที่เล่าสืบต่อกันมา','奶奶给我讲了一个故事。','Nǎi|nai gěi wǒ jiǎng le yí ge gù|shi.','คุณยายเล่านิทานให้ฉันฟังเรื่องหนึ่ง'),
 W('久','jiǔ','นาน','จิ่ว','ใช้บอกว่านาน เช่น 很久 / 好久 / 多久','我等了很久。','Wǒ děng le hěn jiǔ.','ฉันรอมานานมาก'),
 W('梦','mèng','ความฝัน / ฝัน','เมิ่ง','林 (ป่า) + 夕 (ค่ำคืน) = ในป่ายามค่ำคืนที่ภาพลึกลับปรากฏ','我昨晚做了一个好梦。','Wǒ zuó|wǎn zuò le yí ge hǎo mèng.','เมื่อคืนฉันฝันดี'),
 W('长大','zhǎng|dà','โตขึ้น','จ่าง-ต้า','长 (เติบโต) + 大 (ใหญ่) = เติบโตเป็นผู้ใหญ่','孩子们长大了。','Hái|zi|men zhǎng|dà le.','เด็กๆ โตขึ้นแล้ว'),
 W('变成','biàn|chéng','กลายเป็น','เปี้ยน-เฉิง','变 (เปลี่ยน) + 成 (สำเร็จ) = เปลี่ยนจนสำเร็จเป็นอีกอย่าง','小城市变成了大城市。','Xiǎo chéng|shì biàn|chéng le dà chéng|shì.','เมืองเล็กกลายเป็นเมืองใหญ่'),
 W('认为','rèn|wéi','เห็นว่า / คิดว่า','เริ่น-เหวย','认 (รู้จัก) + 为 (เป็น) = ยอมรับว่าเป็นเช่นนั้น','我认为这个办法很好。','Wǒ rèn|wéi zhè|ge bàn|fǎ hěn hǎo.','ฉันคิดว่าวิธีนี้ดีมาก'),
 W('难忘','nán|wàng','ลืมไม่ลง','นาน-หวั่ง','难 (ยาก) + 忘 (ลืม) = ลืมได้ยาก','那天是我最难忘的一天。','Nà tiān shì wǒ zuì nán|wàng de yì tiān.','วันนั้นเป็นวันที่ฉันลืมไม่ลงที่สุด'),
 W('当时','dāng|shí','ตอนนั้น','ตัง-สือ','当 (ตรงกับ) + 时 (เวลา) = ในเวลานั้นพอดี','当时我还很小。','Dāng|shí wǒ hái hěn xiǎo.','ตอนนั้นฉันยังเล็กมาก')],
 sents:[['你/还/记得/我/吗？','nǐ/hái/jì|de/wǒ/ma?','คุณยังจำฉันได้ไหม'],['我/忘记/带/手机/了。','wǒ/wàng|jì/dài/shǒu|jī/le.','ฉันลืมเอามือถือมา'],['这/是/我/第一次/来/中国。','zhè/shì/wǒ/dì|yī|cì/lái/zhōng|guó.','นี่เป็นครั้งแรกที่ฉันมาจีน'],['后来/我们/常常/一起/玩。','hòu|lái/wǒ|men/cháng|cháng/yì|qǐ/wán.','ต่อมาพวกเรามักเล่นด้วยกันบ่อยๆ'],['小时候/我/住/在/奶奶/家。','xiǎo|shí|hou/wǒ/zhù/zài/nǎi|nai/jiā.','ตอนเด็กฉันอาศัยอยู่บ้านคุณยาย'],['他/长大/以后/想/当/医生。','tā/zhǎng|dà/yǐ|hòu/xiǎng/dāng/yī|shēng.','พอโตขึ้นเขาอยากเป็นหมอ']],
 dlg:[['t','你小时候住在哪儿？','Nǐ xiǎo|shí|hou zhù zài nǎ|r?','ตอนเด็กคุณอยู่ที่ไหน'],['f','我小时候住在奶奶家，后来搬到了城市。','Wǒ xiǎo|shí|hou zhù zài nǎi|nai jiā, hòu|lái bān dào le chéng|shì.','ตอนเด็กฉันอยู่บ้านยาย ต่อมาก็ย้ายเข้าเมือง'],['t','你还记得第一次去城市的事吗？','Nǐ hái jì|de dì|yī|cì qù chéng|shì de shì ma?','คุณยังจำเรื่องครั้งแรกที่เข้าเมืองได้ไหม'],['f','当然记得，那是我最难忘的一天。','Dāng|rán jì|de, nà shì wǒ zuì nán|wàng de yì tiān.','แน่นอนว่าจำได้ นั่นเป็นวันที่ฉันลืมไม่ลงที่สุด']],
 rq:{p:0,wrong:[['剧情很感人，配乐也很好听。','Jù|qíng hěn gǎn|rén, pèi|yuè yě hěn hǎo|tīng.','เนื้อเรื่องซึ้งมาก ดนตรีก็ไพเราะ'],['我喜欢秋天，不冷也不热。','wǒ xǐ|huan qiū|tiān, bù lěng yě bú rè.','ฉันชอบฤดูใบไม้ร่วง ไม่หนาวไม่ร้อน']]}},
{id:73,th:'ท้องฟ้า ลม ฝน ต้นไม้',zh:'天空和花草',chapter:27,emoji:'🌤️',
 story:'วันนี้ท้องฟ้าเปลี่ยนไปมา ลามะดูเมฆ ดูดวงอาทิตย์ ดูดาวตอนกลางคืน แล้วเดินชมดอกไม้ต้นไม้ในสวน เรียนคำที่ใช้บอกอากาศและธรรมชาติ',
 words:[
 W('刮','guā','พัด (ลม) / ขูด','กวา','ใช้พูดว่าลมพัด เช่น 刮风 · ในที่นี้เป็นกริยา','外面刮大风。','Wài|miàn guā dà fēng.','ข้างนอกลมแรง'),
 W('下雪','xià|xuě','หิมะตก','เซี่ย-เสวีย','下 (ตก) + 雪 (หิมะ) = หิมะตก','北方冬天常常下雪。','Běi|fāng dōng|tiān cháng|cháng xià|xuě.','ทางเหนือหน้าหนาวมักมีหิมะตก'),
 W('晴天','qíng|tiān','วันที่ฟ้าใส','ฉิง-เทียน','晴 (แจ่มใส) + 天 (ท้องฟ้า/วัน) = วันฟ้าแจ่ม','明天是晴天，我们去爬山吧。','Míng|tiān shì qíng|tiān, wǒ|men qù pá shān ba.','พรุ่งนี้ฟ้าใส เราไปปีนเขากันเถอะ'),
 W('阴天','yīn|tiān','วันที่ฟ้าครึ้ม','อิน-เทียน','阴 (ร่ม/มืดครึ้ม) + 天 = วันที่ฟ้าครึ้ม','今天是阴天，可能会下雨。','Jīn|tiān shì yīn|tiān, kě|néng huì xià yǔ.','วันนี้ฟ้าครึ้ม อาจจะฝนตก'),
 W('凉快','liáng|kuai','เย็นสบาย','เหลียง-ไคว่','凉 (เย็น) + 快 (สบาย) = เย็นสบาย','晚上很凉快，适合出去走走。','Wǎn|shang hěn liáng|kuai, shì|hé chū|qù zǒu|zou.','ตอนเย็นอากาศเย็นสบาย เหมาะกับการออกไปเดินเล่น'),
 W('暖和','nuǎn|huo','อุ่นสบาย','นว่าน-หัว','暖 (อุ่น) + 和 (นุ่มนวล) = อุ่นสบาย','春天到了，天气越来越暖和。','Chūn|tiān dào le, tiān|qì yuè lái yuè nuǎn|huo.','ฤดูใบไม้ผลิมาถึง อากาศอุ่นขึ้นเรื่อย ๆ'),
 W('伞','sǎn','ร่ม','สั่น','ใช้ลักษณะนาม 把 เช่น 一把伞 = ร่มหนึ่งคัน','下雨了，请带一把伞。','Xià yǔ le, qǐng dài yì bǎ sǎn.','ฝนตกแล้ว กรุณาเอาร่มไปหนึ่งคัน'),
 W('云','yún','เมฆ','หยุน','ตัวอักษรเหมือนเมฆลอย','天上的云像一只白兔子。','Tiān shàng de yún xiàng yì zhī bái tù|zi.','เมฆบนฟ้าเหมือนกระต่ายสีขาว'),
 W('太阳','tài|yang','ดวงอาทิตย์','ไท่-หยาง','太 (ยิ่งใหญ่) + 阳 (แสงตะวัน) = ดวงตะวันใหญ่','太阳从东边出来了。','Tài|yang cóng dōng|biān chū|lái le.','ดวงอาทิตย์ขึ้นมาจากทางทิศตะวันออกแล้ว'),
 W('星星','xīng|xing','ดวงดาว','ซิง-ซิง','星 (ดาว) ซ้ำ = ดาวระยิบระยับ','晚上天上有很多星星。','Wǎn|shang tiān shàng yǒu hěn|duō xīng|xing.','ตอนกลางคืนบนฟ้ามีดาวมากมาย'),
 W('低','dī','ต่ำ','ตี','ตรงข้ามกับ 高 · ใช้กับอุณหภูมิ ราคา และเสียง','晚上的气温很低。','Wǎn|shang de qì|wēn hěn dī.','อุณหภูมิตอนกลางคืนต่ำมาก'),
 W('花','huā','ดอกไม้','หัว','ตัวอักษรมี 艹 (หญ้า/พืช) อยู่ด้านบน','公园里的花开了。','Gōng|yuán lǐ de huā kāi le.','ดอกไม้ในสวนสาธารณะบานแล้ว'),
 W('树','shù','ต้นไม้','ชู่','ตัวอักษรมี 木 (ไม้) อยู่ด้านซ้าย','院子里有一棵大树。','Yuàn|zi lǐ yǒu yì kē dà shù.','ในลานบ้านมีต้นไม้ใหญ่หนึ่งต้น'),
 W('草','cǎo','หญ้า','เฉ่า','艹 (หญ้า) อยู่ด้านบน','小朋友们坐在草地上。','Xiǎo péng|you men zuò zài cǎo|dì shàng.','เด็ก ๆ นั่งอยู่บนสนามหญ้า'),
 W('极','jí','มาก ๆ / สุดขีด','จี๋','วางหลังคำคุณศัพท์ + 了 เช่น 热极了 = ร้อนมาก ๆ','今天热极了。','Jīn|tiān rè jí le.','วันนี้ร้อนมาก ๆ'),
 W('蝴蝶','hú|dié','ผีเสื้อ','หู-เหยีย','虫 (แมลง) อยู่ทั้งสองคำ = แมลงมีปีก','花园里飞来了一只蝴蝶。','Huā|yuán lǐ fēi lái le yì zhī hú|dié.','ผีเสื้อตัวหนึ่งบินมาในสวนดอกไม้')],
 sents:[['今天/刮/大/风。','jīn|tiān/guā/dà/fēng.','วันนี้ลมแรง'],['冬天/北方/常常/下雪。','dōng|tiān/běi|fāng/cháng|cháng/xià|xuě.','หน้าหนาวทางเหนือมักมีหิมะตก'],['晴天/的/时候/天/很/蓝。','qíng|tiān/de/shí|hou/tiān/hěn/lán.','วันที่อากาศแจ่มใสท้องฟ้าสีครามมาก'],['晚上/有/很多/星星。','wǎn|shang/yǒu/hěn|duō/xīng|xing.','ตอนกลางคืนมีดาวมากมาย'],['春天/越来越/暖和。','chūn|tiān/yuè|lái|yuè/nuǎn|huo.','ฤดูใบไม้ผลิอุ่นขึ้นเรื่อย ๆ'],['花园/里/有/蝴蝶。','huā|yuán/lǐ/yǒu/hú|dié.','ในสวนดอกไม้มีผีเสื้อ']],
 dlg:[['t','今天天气怎么样？','Jīn|tiān tiān|qì zěn|me|yàng?','วันนี้อากาศเป็นยังไงบ้าง'],['f','是晴天，天很蓝，但是有一点儿风。','Shì qíng|tiān, tiān hěn lán, dàn|shì yǒu yì|diǎn|r fēng.','ฟ้าใส ท้องฟ้าสีฟ้ามาก แต่มีลมนิดหน่อย'],['t','我们去公园看花，好吗？','Wǒ|men qù gōng|yuán kàn huā, hǎo ma?','เราไปดูดอกไม้ที่สวนสาธารณะกันไหม'],['f','好，今天不太热，很凉快。','Hǎo, jīn|tiān bú tài rè, hěn liáng|kuai.','ดี วันนี้ไม่ร้อนมาก เย็นสบาย']],
 rq:{p:0,wrong:[['下象棋吧，我去拿棋盘和棋子。','Xià xiàng|qí ba, wǒ qù ná qí|pán hé qí|zi.','เล่นหมากรุกจีนกัน ฉันไปหยิบกระดานกับตัวหมากมา'],['我想剪短发，再染成黑色。','Wǒ xiǎng jiǎn duǎn|fà, zài rǎn chéng hēi|sè.','ฉันอยากตัดผมสั้นแล้วย้อมเป็นสีดำ']]}},
{id:37,th:'ตัดสินใจและลงมือทำ',zh:'决定和行动',chapter:15,emoji:'🧭',
 story:'ลามะต้องเลือกว่าจะอยู่เรียนต่อหรือรับงานใหม่ เขาลังเล ชั่งใจ แล้วในที่สุดก็ตัดสินใจ และเรียนรู้ว่าความล้มเหลวคือครู',
 words:[
 W('决定','jué|dìng','ตัดสินใจ','เจวี๋ย-ติ้ง','决 (ตัดสิน) + 定 (แน่นอน)','我决定留下来学习。','Wǒ jué|dìng liú xià|lái xué|xí.','ฉันตัดสินใจอยู่เรียนต่อ'),
 W('选择','xuǎn|zé','เลือก / ทางเลือก','เสฺวี่ยน-เจ๋อ','选 (คัด) + 择 (เลือก) สองคำเลือกเหมือนกัน','你有两个选择。','Nǐ yǒu liǎng ge xuǎn|zé.','คุณมีสองทางเลือก'),
 W('办法','bàn|fǎ','วิธี / หนทาง','ป้าน-ฟ่า','办 (จัดการ) + 法 (วิธี) · ใช้บอกว่ามีทางแก้ เช่น 没办法 = ไม่มีทาง','我想到一个好办法。','Wǒ xiǎng dào yí ge hǎo bàn|fǎ.','ฉันนึกวิธีดี ๆ ออกแล้ว'),
 W('自己','zì|jǐ','ตัวเอง','จื้อ-จี่','自 (ตนเอง) + 己 (ตนเอง) · วางหลังคำนามหรือสรรพนามเพื่อเน้น','我想自己决定。','Wǒ xiǎng zì|jǐ jué|dìng.','ฉันอยากตัดสินใจด้วยตัวเอง'),
 W('坚持','jiān|chí','ยืนหยัด / ทำต่อเนื่อง','เจียน-ฉื๋อ','坚 (แข็งแรง) + 持 (ถือไว้) = ถือไว้ไม่ปล่อย','只要坚持，就会成功。','Zhǐ|yào jiān|chí, jiù huì chéng|gōng.','ขอแค่ยืนหยัด ก็จะสำเร็จ'),
 W('成功','chéng|gōng','สำเร็จ','เฉิง๋-กง','成 (กลายเป็น) + 功 (ผลงาน)','他终于成功了。','Tā zhōng|yú chéng|gōng le.','ในที่สุดเขาก็สำเร็จ'),
 W('失败','shī|bài','ล้มเหลว','ซือ-ไป้','失 (สูญเสีย) + 败 (พ่าย)','失败是成功的老师。','Shī|bài shì chéng|gōng de lǎo|shī.','ความล้มเหลวคือครูของความสำเร็จ'),
 W('重要','zhòng|yào','สำคัญ','จ้ง-เย่า','重 (หนัก) + 要 (สำคัญ) = น้ำหนักมาก','健康比钱重要。','Jiàn|kāng bǐ qián zhòng|yào.','สุขภาพสำคัญกว่าเงิน'),
 W('必须','bì|xū','ต้อง (จำเป็นต้อง)','ปี้-ซวี','必 (แน่นอน) + 须 (ต้อง) · ปฏิเสธใช้ 不用 ไม่ใช่ 不必须','你必须按时完成作业。','Nǐ bì|xū àn shí wán|chéng zuò|yè.','คุณต้องทำการบ้านเสร็จตามเวลา'),
 W('可能','kě|néng','อาจจะ / เป็นไปได้','เค่อ-เหนิง','可 (อาจ) + 能 (สามารถ)','明天可能会下雨。','Míng|tiān kě|néng huì xià yǔ.','พรุ่งนี้อาจจะฝนตก'),
 W('一定','yí|dìng','แน่นอน / ต้อง','อี๋-ติ้ง','一 (หนึ่ง) + 定 (กำหนด) = กำหนดไว้ตายตัว','你一定要来！','Nǐ yí|dìng yào lái!','คุณต้องมานะ!'),
 W('马上','mǎ|shàng','ทันที / เดี๋ยวนี้','หม่า-ช่าง','马 (ม้า) + 上 (ขึ้น) = ขึ้นม้าไปเลย (ชั่วพริบตา)','我马上就到。','Wǒ mǎ|shàng jiù dào.','ฉันจะถึงเดี๋ยวนี้แล้ว'),
 W('刚才','gāng|cái','เมื่อครู่นี้','กาง-ไฉ๋','刚 (เพิ่ง) + 才 (เพียง) = เพิ่งเมื่อกี้','我刚才在开会。','Wǒ gāng|cái zài kāi huì.','เมื่อกี้ฉันอยู่ในที่ประชุม'),
 W('发现','fā|xiàn','ค้นพบ / สังเกตเห็น','ฟา-เซี่ยน','发 (ปล่อยออก) + 现 (ปรากฏ) = ทำให้สิ่งซ่อนปรากฏ','我发现自己忘了带钥匙。','Wǒ fā|xiàn zì|jǐ wàng le dài yào|shi.','ฉันสังเกตว่าลืมเอากุญแจมา'),
 W('遇到','yù|dào','พบเจอ / เจอ (ปัญหา)','อวี้-เต้า','遇 (พบ) + 到 (ถึง/สำเร็จ) · ใช้ได้ทั้งเจอคนและเจอปัญหา','我在路上遇到了老同学。','Wǒ zài lù shang yù|dào le lǎo tóng|xué.','ฉันเจอเพื่อนเก่าระหว่างทาง'),
 W('认真','rèn|zhēn','จริงจัง / ตั้งใจ','เริ่น-เจิน','认 (จำ/ยอมรับ) + 真 (จริง) · ใช้ชมคนที่ทำอะไรจริงจัง','他做事很认真。','Tā zuò shì hěn rèn|zhēn.','เขาทำงานจริงจังมาก')],
 sents:[['我/决定/留/下来/学习。','wǒ/jué|dìng/liú/xià|lái/xué|xí.','ฉันตัดสินใจอยู่เรียนต่อ'],['你/有/两/个/选择。','nǐ/yǒu/liǎng/ge/xuǎn|zé.','คุณมีสองทางเลือก'],['只要/坚持，/就/会/成功。','zhǐ|yào/jiān|chí,/jiù/huì/chéng|gōng.','ขอแค่ยืนหยัดก็จะสำเร็จ'],['失败/不/可怕。','shī|bài/bù/kě|pà.','ความล้มเหลวไม่น่ากลัว'],['你/必须/马上/来。','nǐ/bì|xū/mǎ|shàng/lái.','คุณต้องมาเดี๋ยวนี้'],['我/发现/他/刚才/哭/了。','wǒ/fā|xiàn/tā/gāng|cái/kū/le.','ฉันสังเกตว่าเมื่อกี้เขาร้องไห้']],
 dlg:[['t','你决定了吗？','nǐ jué|dìng le ma?','คุณตัดสินใจหรือยัง'],['f','决定了，我会认真做。','jué|dìng le, wǒ huì rèn|zhēn zuò.','ตัดสินใจแล้ว ฉันจะตั้งใจทำ'],['t','很好！失败也没关系。','hěn hǎo! shī|bài yě méi guān|xi.','ดีมาก! ล้มเหลวก็ไม่เป็นไร'],['f','对，坚持最重要。','duì, jiān|chí zuì zhòng|yào.','ใช่ ความยืนหยัดสำคัญที่สุด']],
 rq:{p:2,wrong:[['大概两个小时。','Dà|gài liǎng ge xiǎo|shí.','ประมาณสองชั่วโมง'],['我知道，我已经给它买了笼子和玩具。','Wǒ zhī|dào, wǒ yǐ|jīng gěi tā mǎi le lóng|zi hé wán|jù.','ฉันรู้ ฉันซื้อกรงกับของเล่นให้มันแล้ว']]}},
{id:38,th:'คำเชื่อมประโยค',zh:'连接词',chapter:15,emoji:'🔗',
 story:'ครูจีนสอนลามะให้เล่าเรื่องเป็นลำดับและให้เหตุผลด้วยคำเชื่อม ถ้า… ยกเว้น… ไม่ว่า… ขอแค่… แล้วประโยคก็ยาวและไพเราะขึ้น',
 words:[
 W('首先','shǒu|xiān','ก่อนอื่น','โส่ว-เซียน','首 (หัว/แรก) + 先 (ก่อน)','首先，我要谢谢大家。','Shǒu|xiān, wǒ yào xiè|xie dà|jiā.','ก่อนอื่น ฉันขอขอบคุณทุกคน'),
 W('而且','ér|qiě','และยัง / อีกทั้ง','เอ๋อร์-เฉี่ย','ใช้เติมข้อดี/ข้อมูลเพิ่มจากประโยคก่อน เช่น 很好，而且很便宜','这里很安静，而且很便宜。','Zhè|lǐ hěn ān|jìng, ér|qiě hěn pián|yi.','ที่นี่เงียบ และยังถูกด้วย'),
 W('如果','rú|guǒ','ถ้า','หรู๋-กั่ว','如 (ถ้าหาก) + 果 (ผล)','如果明天下雨，我们就不去。','Rú|guǒ míng|tiān xià yǔ, wǒ|men jiù bú qù.','ถ้าพรุ่งนี้ฝนตก เราก็ไม่ไป'),
 W('除了','chú|le','นอกจาก / ยกเว้น','ฉู๋-เลอ','除 (กำจัด/ยกออก) + 了','除了我，大家都来了。','Chú|le wǒ, dà|jiā dōu lái le.','นอกจากฉัน ทุกคนมาแล้ว'),
 W('或者','huò|zhě','หรือ (ในประโยคบอกเล่า)','ฮั่ว-เจ่อ','ใช้ในประโยคบอกเล่า เลือกอย่างใดอย่างหนึ่ง · ประโยคคำถามใช้ 还是','我们坐地铁或者打车去。','Wǒ|men zuò dì|tiě huò|zhě dǎ chē qù.','เรานั่งรถไฟใต้ดินหรือเรียกแท็กซี่ไป'),
 W('无论','wú|lùn','ไม่ว่า…','อู๋-หลุ่น','无 (ไม่มี) + 论 (พูดถึง) = ไม่ต้องพูดถึง','无论多忙，我都会来。','Wú|lùn duō máng, wǒ dōu huì lái.','ไม่ว่ายุ่งแค่ไหน ฉันก็จะมา'),
 W('只要','zhǐ|yào','ขอแค่ / ตราบใดที่','จื่อ-เย่า','只 (เพียง) + 要 (ต้องการ)','只要努力，你就能学好。','Zhǐ|yào nǔ|lì, nǐ jiù néng xué hǎo.','ขอแค่พยายาม คุณก็เรียนได้ดี'),
 W('只有','zhǐ|yǒu','มีเพียง…เท่านั้น','จื่อ-โหย่ว','只 (เพียง) + 有 (มี)','只有你知道这个秘密。','Zhǐ|yǒu nǐ zhī|dào zhè|ge mì|mì.','มีเพียงคุณที่รู้ความลับนี้'),
 W('当然','dāng|rán','แน่นอน / ย่อมอยู่แล้ว','ตัง-หราน','当 (ควรจะ) + 然 (เป็นเช่นนั้น)','当然可以！','Dāng|rán kě|yǐ!','ได้แน่นอน!'),
 W('为了','wèi|le','เพื่อ (จุดประสงค์)','เว่ย-เลอ','บอกจุดประสงค์ เช่น 为了健康 = เพื่อสุขภาพ · ต่างจาก 为什么 (ทำไม)','为了学好汉语，我每天练习。','Wèi|le xué hǎo Hàn|yǔ, wǒ měi tiān liàn|xí.','เพื่อเรียนภาษาจีนให้ดี ฉันฝึกทุกวัน'),
 W('简单','jiǎn|dān','ง่าย / เรียบง่าย','เจี่ยน-ตาน','简 (สั้น) + 单 (เดี่ยว)','这个办法很简单。','Zhè|ge bàn|fǎ hěn jiǎn|dān.','วิธีนี้ง่ายมาก'),
 W('一边','yì|biān','ไปพลางทำพลาง (ทำสองอย่างพร้อมกัน)','อี้-เปียน','ใช้ซ้ำสองครั้งหน้ากริยา: 一边…一边… · ตัว 一 อ่านเสียง 4 เพราะตามด้วยเสียง 1','我一边走路，一边听音乐。','Wǒ yì|biān zǒu lù, yì|biān tīng yīn|yuè.','ฉันเดินไปฟังเพลงไป'),
 W('关于','guān|yú','เกี่ยวกับ','กวน-หวีว','关 (เกี่ยวข้อง) + 于 (ที่/ต่อ) · ใช้นำหัวข้อ เช่น 关于中国','我想看关于中国的书。','Wǒ xiǎng kàn guān|yú Zhōng|guó de shū.','ฉันอยากอ่านหนังสือเกี่ยวกับจีน'),
 W('一般','yì|bān','ทั่วไป / โดยปกติ','อี้-ปาน','一 (หนึ่ง) + 般 (ชนิด) = แบบเดียวกันทั่วไป','我一般七点起床。','Wǒ yì|bān qī diǎn qǐ chuáng.','โดยปกติฉันตื่นเจ็ดโมง'),
 W('越来越','yuè lái yuè','ยิ่งนานยิ่ง…','เยว่-ไหล๋-เยว่','越 (ยิ่ง) + 来 (มา) + 越 (ยิ่ง) = ยิ่งมา ยิ่งเป็น','天气越来越冷了。','Tiān|qì yuè lái yuè lěng le.','อากาศหนาวขึ้นเรื่อย ๆ'),
 W('比较','bǐ|jiào','ค่อนข้าง / เปรียบเทียบ','ปี่-เจี้ยว','比 (เทียบ) + 较 (เปรียบ)','这个比较便宜。','Zhè|ge bǐ|jiào pián|yi.','อันนี้ค่อนข้างถูก')],
 sents:[['首先，/我/要/谢谢/大家。','shǒu|xiān,/wǒ/yào/xiè|xie/dà|jiā.','ก่อนอื่น ฉันขอขอบคุณทุกคน'],['如果/下雨，/我们/就/不/去。','rú|guǒ/xià yǔ,/wǒ|men/jiù/bú/qù.','ถ้าฝนตกเราก็ไม่ไป'],['无论/多/忙，/我/都/会/来。','wú|lùn/duō/máng,/wǒ/dōu/huì/lái.','ไม่ว่ายุ่งแค่ไหนฉันก็มา'],['只要/努力，/就/会/进步。','zhǐ|yào/nǔ|lì,/jiù/huì/jìn|bù.','ขอแค่พยายามก็จะก้าวหน้า'],['除了/我，/大家/都/来/了。','chú|le/wǒ,/dà|jiā/dōu/lái/le.','นอกจากฉัน ทุกคนมาแล้ว'],['天气/越来越/冷/了。','tiān|qì/yuè lái yuè/lěng/le.','อากาศหนาวขึ้นเรื่อย ๆ']],
 dlg:[['t','如果明天下雨，你还去吗？','rú|guǒ míng|tiān xià yǔ, nǐ hái qù ma?','ถ้าพรุ่งนี้ฝนตก คุณจะไปไหม'],['f','当然去，无论天气怎么样。','dāng|rán qù, wú|lùn tiān|qì zěn|me|yàng.','ไปแน่นอน ไม่ว่าอากาศเป็นยังไง'],['t','只要你去，我也去。','zhǐ|yào nǐ qù, wǒ yě qù.','ขอแค่คุณไป ฉันก็ไป'],['f','太好了，首先我们买票！','tài hǎo le, shǒu|xiān wǒ|men mǎi piào!','ดีเลย ก่อนอื่นเราไปซื้อตั๋วกัน']],
 rq:{p:2,wrong:[['双手合十，微笑一下，就很礼貌了。','Shuāng shǒu hé|shí, wēi|xiào yí|xià, jiù hěn lǐ|mào le.','พนมมือแล้วยิ้ม ก็สุภาพมากแล้ว'],['带旧衣物就可以了。','Dài jiù yī|wù jiù kě|yǐ le.','เอาเสื้อผ้าเก่าไปก็พอ']]}},
{id:74,th:'ห้องเรียนและวิชาเรียน',zh:'教室里',chapter:28,emoji:'🎒',
 story:'ลามะเดินเข้าห้องเรียนใหม่ เจอกระดานดำ ดินสอ หนังสือเรียน และตารางวิชา เรียนคำที่ใช้ในโรงเรียนทุกวัน และบอกว่าชอบวิชาไหน',
 words:[
 W('数学','shù|xué','คณิตศาสตร์','ชู่-เสวีย','数 (ตัวเลข) + 学 (เรียน) = วิชาตัวเลข','我觉得数学很有意思。','Wǒ jué|de shù|xué hěn yǒu yì|si.','ฉันคิดว่าคณิตศาสตร์น่าสนใจมาก'),
 W('英语','yīng|yǔ','ภาษาอังกฤษ','อิง-หยวี่','英 (อังกฤษ) + 语 (ภาษา) = ภาษาอังกฤษ','我们每天都有英语课。','Wǒ|men měi|tiān dōu yǒu yīng|yǔ kè.','เรามีเรียนภาษาอังกฤษทุกวัน'),
 W('语文','yǔ|wén','วิชาภาษาจีน','หยวี่-เหวิน','语 (ภาษา) + 文 (ตัวอักษร) = วิชาภาษาและวรรณคดีของจีน','语文课上我们读故事。','Yǔ|wén kè shàng wǒ|men dú gù|shi.','ในคาบภาษาจีนเราอ่านเรื่องเล่า'),
 W('地理','dì|lǐ','ภูมิศาสตร์','ตี้-หลี่','地 (แผ่นดิน) + 理 (หลักการ) = ความรู้เรื่องผืนแผ่นดิน','地理老师很会讲故事。','Dì|lǐ lǎo|shī hěn huì jiǎng gù|shi.','ครูภูมิศาสตร์เล่าเรื่องเก่งมาก'),
 W('美术','měi|shù','ศิลปะ / วาดภาพ','เหม่ย-ชู่','美 (สวย) + 术 (ศิลป์) = ศิลปะแห่งความงาม','美术课上我画了一只熊猫。','Měi|shù kè shàng wǒ huà le yì zhī xióng|māo.','ในคาบศิลปะฉันวาดแพนด้าหนึ่งตัว'),
 W('班','bān','ห้องเรียน / ชั้นเรียน','ปาน','班 คือกลุ่มคนที่เรียนด้วยกัน','我们班有三十个学生。','Wǒ|men bān yǒu sān|shí ge xué|sheng.','ห้องของเรามีนักเรียนสามสิบคน'),
 W('课本','kè|běn','หนังสือเรียน','เค่อ-เปิ่น','课 (บทเรียน) + 本 (เล่ม) = หนังสือเรียน','请把课本打开第五页。','Qǐng bǎ kè|běn dǎ|kāi dì wǔ yè.','ช่วยเปิดหนังสือเรียนหน้าที่ห้า'),
 W('黑板','hēi|bǎn','กระดานดำ','เฮย-ป่าน','黑 (ดำ) + 板 (แผ่น) = แผ่นสีดำ','老师在黑板上写了一个字。','Lǎo|shī zài hēi|bǎn shàng xiě le yí ge zì.','ครูเขียนตัวอักษรหนึ่งตัวบนกระดานดำ'),
 W('铅笔','qiān|bǐ','ดินสอ','เชียน-บี่','铅 (ตะกั่ว/ไส้ดินสอ) + 笔 (ปากกา) = ดินสอ','我的铅笔不见了。','Wǒ de qiān|bǐ bú|jiàn le.','ดินสอของฉันหายไปแล้ว'),
 W('字典','zì|diǎn','พจนานุกรมตัวอักษรจีน','จื้อ-เตี่ยน','字 (ตัวอักษร) + 典 (ตำรา) · ใช้เปิดหาตัวอักษรที่ไม่รู้จัก','我用字典查汉字。','Wǒ yòng zì|diǎn chá Hàn|zì.','ฉันใช้พจนานุกรมเปิดหาตัวอักษรจีน'),
 W('年级','nián|jí','ชั้นปี','เหนียน-จี๋','年 (ปี) + 级 (ระดับ) · เช่น 三年级 = ชั้นปีที่สาม','我是三年级的学生。','Wǒ shì sān nián|jí de xué|sheng.','ฉันเป็นนักเรียนชั้นปีที่สาม'),
 W('书包','shū|bāo','กระเป๋านักเรียน','ชู-เปา','书 (หนังสือ) + 包 (กระเป๋า) = กระเป๋าใส่หนังสือ','他的书包又大又重。','Tā de shū|bāo yòu dà yòu zhòng.','กระเป๋านักเรียนของเขาทั้งใหญ่และหนัก'),
 W('教室','jiào|shì','ห้องเรียน (อาคาร/ห้อง)','เจี้ยว-ชื่อ','教 (สอน) + 室 (ห้อง) = ห้องสอน','教室里没有人。','Jiào|shì lǐ méi|yǒu rén.','ในห้องเรียนไม่มีคน'),
 W('校长','xiào|zhǎng','ผู้อำนวยการโรงเรียน / อธิการบดี','เซี่ยว-จ่าง','校 (โรงเรียน) + 长 (หัวหน้า) · ในคำนี้ 长 อ่าน zhǎng','校长在教室里讲话。','Xiào|zhǎng zài jiào|shì lǐ jiǎng huà.','ผู้อำนวยการพูดอยู่ในห้องเรียน'),
 W('图书馆','tú|shū|guǎn','ห้องสมุด','ถู-ชู-กว่าน','图 (ภาพ) + 书 (หนังสือ) + 馆 (อาคาร) = อาคารหนังสือ','我常常去图书馆看书。','Wǒ cháng|cháng qù tú|shū|guǎn kàn shū.','ฉันมักไปอ่านหนังสือที่ห้องสมุด'),
 W('放学','fàng|xué','เลิกเรียน (กลับบ้าน)','ฟั่ง-เสวีย','放 (ปล่อย) + 学 (เรียน) = ปล่อยจากการเรียน','几点放学？','Jǐ diǎn fàng|xué?','เลิกเรียนกี่โมง')],
 sents:[['我/最/喜欢/美术课。','wǒ/zuì/xǐ|huan/měi|shù|kè.','ฉันชอบคาบศิลปะที่สุด'],['老师/在/黑板/上/写字。','lǎo|shī/zài/hēi|bǎn/shàng/xiě zì.','ครูเขียนหนังสือบนกระดานดำ'],['请/拿/出/你/的/课本。','qǐng/ná/chū/nǐ/de/kè|běn.','ช่วยหยิบหนังสือเรียนของคุณออกมา'],['我/想/借/一/支/铅笔。','wǒ/xiǎng/jiè/yì/zhī/qiān|bǐ.','ฉันอยากยืมดินสอหนึ่งแท่ง'],['放学/以后/我/去/图书馆。','fàng|xué/yǐ|hòu/wǒ/qù/tú|shū|guǎn.','เลิกเรียนแล้วฉันไปห้องสมุด'],['我们/班/有/三十/个/学生。','wǒ|men/bān/yǒu/sān|shí/ge/xué|sheng.','ห้องเรามีนักเรียนสามสิบคน']],
 dlg:[['t','你今天有什么课？','Nǐ jīn|tiān yǒu shén|me kè?','วันนี้คุณมีเรียนวิชาอะไรบ้าง'],['f','上午有数学和英语，下午有美术。','Shàng|wǔ yǒu shù|xué hé yīng|yǔ, xià|wǔ yǒu měi|shù.','ช่วงเช้ามีคณิตและอังกฤษ ช่วงบ่ายมีศิลปะ'],['t','你喜欢哪一门课？','Nǐ xǐ|huan nǎ yì mén kè?','คุณชอบวิชาไหนที่สุด'],['f','我喜欢地理，因为可以看很多地图。','Wǒ xǐ|huan dì|lǐ, yīn|wèi kě|yǐ kàn hěn|duō dì|tú.','ฉันชอบภูมิศาสตร์ เพราะได้ดูแผนที่เยอะ']],
 rq:{p:0,wrong:[['外带，请给我一根吸管。','Wài|dài, qǐng gěi wǒ yì gēn xī|guǎn.','ห่อกลับ ขอหลอดหนึ่งอันด้วยครับ'],['他们都很友好，房东也不错。','tā|men dōu hěn yǒu|hǎo, fáng|dōng yě bú cuò.','เป็นมิตรทุกคน เจ้าของห้องก็ดีด้วย']]}},
{id:75,th:'ไปห้องพยาบาลและร้านยา',zh:'看病',chapter:28,emoji:'🩺',
 story:'ลามะรู้สึกไม่สบายเลยไปหาหมอ ลงทะเบียน บอกว่าเจ็บตรงไหน แล้วไปร้านขายยา เรียนชื่ออวัยวะและประโยคที่ใช้ตอนไม่สบาย',
 words:[
 W('护士','hù|shi','พยาบาล','ฮู่-ชื่อ','护 (ดูแล) + 士 (ผู้ทำงานเฉพาะทาง) = ผู้ดูแลคนป่วย','护士给我量了体温。','Hù|shi gěi wǒ liáng le tǐ|wēn.','พยาบาลวัดอุณหภูมิให้ฉัน'),
 W('牙','yá','ฟัน','หยา','ตัวอักษรเหมือนฟันสองซี่ไขว้กัน','我的牙很疼。','Wǒ de yá hěn téng.','ฟันของฉันปวดมาก'),
 W('耳朵','ěr|duo','หู','เอ่อร์-ตัว','耳 (หู) + 朵 (ดอก/ชิ้น) = หู','我的耳朵有点儿疼。','Wǒ de ěr|duo yǒu|diǎn|r téng.','หูฉันปวดนิดหน่อย'),
 W('嘴','zuǐ','ปาก','จุ่ย','口 (ปาก) อยู่ซ้ายของตัวอักษร','请张开嘴，说“啊”。','Qǐng zhāng kāi zuǐ, shuō “ā”.','โปรดอ้าปากแล้วพูดว่า “อา”'),
 W('腿','tuǐ','ขา','ทุ่ย','月 (เนื้อ/ร่างกาย) อยู่ซ้าย','我的腿很累。','Wǒ de tuǐ hěn lèi.','ขาของฉันเมื่อยมาก'),
 W('看病','kàn|bìng','ไปหาหมอ','คั้น-ปิ้ง','看 (ดู) + 病 (ป่วย) = ให้หมอดูอาการป่วย','我今天要去医院看病。','Wǒ jīn|tiān yào qù yī|yuàn kàn|bìng.','วันนี้ฉันต้องไปหาหมอที่โรงพยาบาล'),
 W('饱','bǎo','อิ่ม','เป่า','ตรงข้ามกับ 饿 (หิว) · 吃饱了 = กินอิ่มแล้ว','我吃饱了。','Wǒ chī bǎo le.','ฉันกินอิ่มแล้ว'),
 W('药店','yào|diàn','ร้านขายยา','เย่า-เตี้ยน','药 (ยา) + 店 (ร้าน) = ร้านขายยา','药店就在医院旁边。','Yào|diàn jiù zài yī|yuàn páng|biān.','ร้านขายยาอยู่ข้างโรงพยาบาลพอดี'),
 W('鼻子','bí|zi','จมูก','ปี๋-จึ','鼻 (จมูก) + 子 (ตัว) = จมูก','感冒了，我的鼻子不舒服。','Gǎn|mào le, wǒ de bí|zi bù shū|fu.','เป็นหวัดแล้ว จมูกฉันไม่สบาย'),
 W('头发','tóu|fa','ผม','โถว-ฟะ','头 (หัว) + 发 (ผม) = ผมบนหัว','她的头发又黑又长。','Tā de tóu|fa yòu hēi yòu cháng.','ผมของเธอทั้งดำและยาว'),
 W('脸','liǎn','ใบหน้า','เหลี่ยน','月 (เนื้อ/ร่างกาย) อยู่ซ้าย','你的脸怎么这么红？','Nǐ de liǎn zěn|me zhè|me hóng?','หน้าคุณทำไมแดงขนาดนี้'),
 W('注意','zhù|yì','ระวัง / ใส่ใจ','จู้-อี้','注 (จดจ่อ) + 意 (ความคิด) · ใช้เตือน เช่น 请注意 = โปรดระวัง','吃药以后要注意休息。','Chī yào yǐ|hòu yào zhù|yì xiū|xi.','หลังกินยาต้องใส่ใจพักผ่อน'),
 W('放心','fàng|xīn','ไว้ใจ / สบายใจ ไม่ต้องห่วง','ฟ่าง-ซิน','放 (วาง) + 心 (ใจ) = วางใจลงได้','医生说我可以放心。','Yī|shēng shuō wǒ kě|yǐ fàng|xīn.','หมอบอกว่าฉันไม่ต้องกังวล'),
 W('刷','shuā','แปรง / ถู','ซวา','ใช้กับ 刷牙 (แปรงฟัน) และ 刷卡 (รูดบัตร)','早上和晚上都要刷牙。','Zǎo|shang hé wǎn|shang dōu yào shuā yá.','ต้องแปรงฟันทั้งเช้าและเย็น'),
 W('洗手间','xǐ|shǒu|jiān','ห้องน้ำ','สี่-โส่ว-เจียน','洗手 (ล้างมือ) + 间 (ห้อง) = ห้องที่ใช้ล้างมือ · เป็นคำสุภาพสำหรับห้องน้ำ','请问，洗手间在那边。','Qǐng|wèn, xǐ|shǒu|jiān zài nà|biān.','ขอถามหน่อย ห้องน้ำอยู่ทางโน้น'),
 W('小心','xiǎo|xīn','ระวัง','เสี่ยว-ซิน','小 (เล็ก) + 心 (ใจ) = ใส่ใจให้ละเอียด','路很滑，请小心。','Lù hěn huá, qǐng xiǎo|xīn.','ถนนลื่นมาก โปรดระวัง')],
 sents:[['我/头/疼，/想/去/看病。','wǒ/tóu/téng,/xiǎng/qù/kàn|bìng.','ฉันปวดหัว อยากไปหาหมอ'],['请/先/注意/休息。','qǐng/xiān/zhù|yì/xiū|xi.','ขอให้พักผ่อนให้พอก่อน'],['护士/给/我/量/体温。','hù|shi/gěi/wǒ/liáng/tǐ|wēn.','พยาบาลวัดอุณหภูมิให้ฉัน'],['我/的/牙/很/疼。','wǒ/de/yá/hěn/téng.','ฟันฉันปวดมาก'],['药店/在/医院/旁边。','yào|diàn/zài/yī|yuàn/páng|biān.','ร้านขายยาอยู่ข้างโรงพยาบาล'],['路/很/滑，/请/小心。','lù/hěn/huá,/qǐng/xiǎo|xīn.','ถนนลื่น โปรดระวัง']],
 dlg:[['t','你哪里不舒服？','Nǐ nǎ|lǐ bù shū|fu?','คุณไม่สบายตรงไหน'],['f','我的嘴很疼，还有点儿发烧。','Wǒ de zuǐ hěn téng, hái yǒu|diǎn|r fā|shāo.','ปากฉันเจ็บมาก แล้วก็มีไข้นิดหน่อย'],['t','先吃药，多休息，不要太累。','Xiān chī yào, duō xiū|xi, bú|yào tài lèi.','กินยาก่อน พักผ่อนเยอะ ๆ อย่าเหนื่อยเกินไป'],['f','好的，谢谢医生。','Hǎo de, xiè|xie yī|shēng.','ได้ครับ ขอบคุณคุณหมอ']],
 rq:{p:0,wrong:[['我喜欢蓝色和白色。','wǒ xǐ|huan lán sè hé bái sè.','ฉันชอบสีฟ้ากับสีขาว'],['我要一杯牛奶。','wǒ yào yì bēi niú|nǎi.','ฉันเอานมหนึ่งแก้ว']]}},
{id:42,th:'ย้ายบ้านและจัดห้อง',zh:'搬家和整理',chapter:17,emoji:'🏠',
 story:'ลามะเช่าห้องใหม่ใกล้มหาวิทยาลัย ต้องย้ายบ้าน ทำความรู้จักเพื่อนบ้าน คุยกับเจ้าของห้อง และดูห้องครัวกับตู้เย็นว่าใช้ได้ไหม',
 words:[
 W('搬家','bān jiā','ย้ายบ้าน','ปาน-เจีย','搬 (ขนย้าย) + 家 (บ้าน)','我们下个月搬家。','Wǒ|men xià ge yuè bān jiā.','เดือนหน้าเราย้ายบ้าน'),
 W('租房','zū fáng','เช่าห้อง','จู-ฟั๋ง','租 (เช่า) + 房 (ห้อง/บ้าน)','我在学校附近租房。','Wǒ zài xué|xiào fù|jìn zū fáng.','ฉันเช่าห้องใกล้โรงเรียน'),
 W('房东','fáng|dōng','เจ้าของห้องเช่า','ฟั๋ง-ตง','房 (บ้าน) + 东 (เจ้าของ ตามธรรมเนียมเก่า)','房东人很好。','Fáng|dōng rén hěn hǎo.','เจ้าของห้องเป็นคนดีมาก'),
 W('邻居','lín|jū','เพื่อนบ้าน','หลิน๋-จวี','邻 (ติดกัน) + 居 (อาศัย)','我的邻居很友好。','Wǒ de lín|jū hěn yǒu|hǎo.','เพื่อนบ้านของฉันเป็นมิตรมาก'),
 W('厨房','chú|fáng','ห้องครัว','ฉู๋-ฟั๋ง','厨 (ทำอาหาร) + 房 (ห้อง)','妈妈在厨房做饭。','Mā|ma zài chú|fáng zuò fàn.','แม่ทำอาหารอยู่ในครัว'),
 W('层','céng','ชั้น (ของอาคาร) / ชั้น','เฉิง','ใช้นับชั้นของอาคาร เช่น 十层 · ยังใช้เรียกชั้นซ้อนกัน','我家在十层。','Wǒ jiā zài shí céng.','บ้านฉันอยู่ชั้นสิบ'),
 W('楼','lóu','ตึก / ชั้น (ในตึก)','โหลว','ใช้ได้ทั้งตึก (大楼) และชั้นของตึก (二楼 = ชั้นสอง) · ชั้นล่างเรียก 一楼','我家在二楼。','Wǒ jiā zài èr lóu.','บ้านฉันอยู่ชั้นสอง'),
 W('放','fàng','วาง / ใส่ / ปล่อย','ฟ่าง','ใช้ได้ทั้งวางของและปล่อยเวลา เช่น 放假 (หยุดงาน) · 放在 = วางไว้ที่','请把牛奶放在冰箱里。','Qǐng bǎ niú|nǎi fàng zài bīng|xiāng lǐ.','กรุณาใส่นมไว้ในตู้เย็น'),
 W('拿','ná','ถือ / หยิบ','หนา','มี 手 (มือ) อยู่ในตัวอักษร ใช้กับการหยิบถือด้วยมือ · 拿来 = เอามา','我来拿这个箱子。','Wǒ lái ná zhè ge xiāng|zi.','ฉันช่วยถือกล่องนี้เอง'),
 W('冰箱','bīng|xiāng','ตู้เย็น','ปิง-เซียง','冰 (น้ำแข็ง) + 箱 (กล่อง)','牛奶在冰箱里。','Niú|nǎi zài bīng|xiāng lǐ.','นมอยู่ในตู้เย็น'),
 W('离开','lí|kāi','ออกจาก / จากไป','หลี-ไค','离 (ห่างจาก) + 开 (เปิด/ออก) · ใช้ได้ทั้งออกจากที่หรือจากคน','我下个月离开这里。','Wǒ xià ge yuè lí|kāi zhè|lǐ.','เดือนหน้าฉันจะย้ายออกจากที่นี่'),
 W('打扫','dǎ|sǎo','กวาดถู / ทำความสะอาด','ต่า-ส่าว','打 (ทำ) + 扫 (กวาด)','周末我打扫房间。','Zhōu|mò wǒ dǎ|sǎo fáng|jiān.','สุดสัปดาห์ฉันทำความสะอาดห้อง'),
 W('整理','zhěng|lǐ','จัดให้เป็นระเบียบ','เจิ่ง-หลี่','整 (ทั้งหมด/เรียบร้อย) + 理 (จัดการ)','请整理一下你的书桌。','Qǐng zhěng|lǐ yí|xià nǐ de shū|zhuō.','ช่วยจัดโต๊ะหนังสือของคุณหน่อย'),
 W('乱','luàn','รก / วุ่นวาย','ล่วน','舌 (ลิ้น) + 乚 = สับสนวุ่นวาย','房间太乱了。','Fáng|jiān tài luàn le.','ห้องรกเกินไปแล้ว'),
 W('安静','ān|jìng','เงียบสงบ','อัน-จิ้ง','安 (สงบ) + 静 (นิ่ง)','这里很安静，适合学习。','Zhè|lǐ hěn ān|jìng, shì|hé xué|xí.','ที่นี่เงียบสงบ เหมาะกับการเรียน'),
 W('方便','fāng|biàn','สะดวก','ฟาง-เบี้ยน','方 (ทิศ/วิธี) + 便 (สะดวก)','这里的交通很方便。','Zhè|lǐ de jiāo|tōng hěn fāng|biàn.','การเดินทางที่นี่สะดวกมาก')],
 sents:[['我们/下/个/月/搬家。','wǒ|men/xià/ge/yuè/bān jiā.','เดือนหน้าเราย้ายบ้าน'],['我/的/邻居/很/友好。','wǒ/de/lín|jū/hěn/yǒu|hǎo.','เพื่อนบ้านฉันเป็นมิตร'],['牛奶/在/冰箱/里。','niú|nǎi/zài/bīng|xiāng/lǐ.','นมอยู่ในตู้เย็น'],['周末/我/打扫/房间。','zhōu|mò/wǒ/dǎ|sǎo/fáng|jiān.','สุดสัปดาห์ฉันทำความสะอาดห้อง'],['房间/太/乱/了。','fáng|jiān/tài/luàn/le.','ห้องรกเกินไปแล้ว'],['这里/交通/很/方便。','zhè|lǐ/jiāo|tōng/hěn/fāng|biàn.','ที่นี่เดินทางสะดวก']],
 dlg:[['t','你的新房子怎么样？','nǐ de xīn fáng|zi zěn|me|yàng?','บ้านใหม่คุณเป็นยังไงบ้าง'],['f','很安静，也很方便。','hěn ān|jìng, yě hěn fāng|biàn.','เงียบดีและสะดวกด้วย'],['t','邻居呢？','lín|jū ne?','แล้วเพื่อนบ้านล่ะ'],['f','他们都很友好，房东也不错。','tā|men dōu hěn yǒu|hǎo, fáng|dōng yě bú cuò.','เป็นมิตรทุกคน เจ้าของห้องก็ดีด้วย']],
 rq:{p:2,wrong:[['我不太同意，原因有两个。','wǒ bú tài tóng|yì, yuán|yīn yǒu liǎng ge.','ฉันไม่ค่อยเห็นด้วย เหตุผลมีสองข้อ'],['我想剪短，再烫发。','Wǒ xiǎng jiǎn duǎn, zài tàng|fà.','ฉันอยากตัดสั้น แล้วก็ดัดผมด้วย']]}}
);
